// ── Saved views (Feature B — "Saved views over the meetings list") ─────────────────────────────
//
// LOCK-SECURITY NOTE: the four saved-view commands below (`list_saved_views` / `upsert_saved_view`
// / `delete_saved_view` / `reorder_saved_views`) are the ONE legitimate NEW-command case that is
// NOT content-gated. They persist only a user's VIEW DEFINITION (an opaque FE-owned `config` JSON
// blob + presentation fields) — single-user, non-shared metadata, exactly like the `saved_recipes`
// commands. They store/return NO meeting content, so there is nothing sealed to leak. The ACTUAL
// content aggregation the meetings surface consumes is `list_meeting_action_summaries`, which IS
// gated (routes through `unlocked_snapshot` → the gated `Db::list_meeting_action_summaries`).

/// The valid saved-view scopes — one per list surface. A scope not in this set is rejected as an
/// argument error so a typo can't quietly create an un-listable orphan row. `"notes"` was added
/// 2026-07-14 (Saved Views ported to the Notes surface, mirroring Meetings).
const SAVED_VIEW_SCOPE_MEETINGS: &str = "meetings";
const SAVED_VIEW_SCOPE_NOTES: &str = "notes";

/// Whether `scope` names a list surface that supports saved views.
fn is_valid_saved_view_scope(scope: &str) -> bool {
    scope == SAVED_VIEW_SCOPE_MEETINGS || scope == SAVED_VIEW_SCOPE_NOTES
}

/// List the user's saved views for a list surface (`scope` = "meetings"). NOT content-gated: view
/// metadata only (see the LOCK-SECURITY NOTE above).
#[tauri::command]
pub fn list_saved_views(
    state: State<'_, AppState>,
    scope: String,
) -> Result<Vec<SavedView>, AppError> {
    if !is_valid_saved_view_scope(&scope) {
        return Err(AppError::InvalidArg(format!(
            "unsupported saved-view scope: {scope}"
        )));
    }
    state.db.list_saved_views(&scope)
}

/// Create or update a saved view. On FIRST save (empty `id`) the server generates the id +
/// `created_at`; `updated_at` is always stamped server-side. Trims + rejects empty name/scope/layout
/// as an argument error. NOT content-gated: view metadata only (see the LOCK-SECURITY NOTE above).
#[tauri::command]
pub fn upsert_saved_view(
    state: State<'_, AppState>,
    view: SavedView,
) -> Result<SavedView, AppError> {
    let scope = view.scope.trim();
    let name = view.name.trim();
    let layout = view.layout.trim();
    if !is_valid_saved_view_scope(scope) {
        return Err(AppError::InvalidArg(format!(
            "unsupported saved-view scope: {scope}"
        )));
    }
    if name.is_empty() || layout.is_empty() {
        return Err(AppError::InvalidArg(
            "saved-view name and layout are required".into(),
        ));
    }
    let now = chrono::Utc::now().to_rfc3339();
    let id = view.id.trim();
    let (id, created_at) = if id.is_empty() {
        // First save: server-generate the id + creation timestamp.
        (uuid::Uuid::new_v4().to_string(), now.clone())
    } else {
        // Edit: keep the caller's id; preserve the original created_at if we already have the row.
        let created_at = state
            .db
            .list_saved_views(scope)?
            .into_iter()
            .find(|v| v.id == id)
            .map(|v| v.created_at)
            .unwrap_or_else(|| now.clone());
        (id.to_string(), created_at)
    };
    let rec = SavedView {
        id,
        scope: scope.to_string(),
        name: name.to_string(),
        layout: layout.to_string(),
        config: view.config,
        sort_order: view.sort_order,
        created_at,
        updated_at: now,
    };
    state.db.upsert_saved_view(&rec)?;
    Ok(rec)
}

/// Delete a saved view by id (idempotent). NOT content-gated: view metadata only.
#[tauri::command]
pub fn delete_saved_view(state: State<'_, AppState>, id: String) -> Result<(), AppError> {
    state.db.delete_saved_view(&id)
}

/// Persist a user reordering of the saved views in a scope. NOT content-gated: view metadata only.
#[tauri::command]
pub fn reorder_saved_views(
    state: State<'_, AppState>,
    scope: String,
    ordered_ids: Vec<String>,
) -> Result<(), AppError> {
    if !is_valid_saved_view_scope(&scope) {
        return Err(AppError::InvalidArg(format!(
            "unsupported saved-view scope: {scope}"
        )));
    }
    state.db.reorder_saved_views(&scope, &ordered_ids)
}

/// Per-meeting open/done action-item counts across the VISIBLE library, for the saved-views meetings
/// surface. GATED: routes the LIVE session unlock set through `Db::list_meeting_action_summaries`
/// (`list_meetings_visible` + `get_note_if_visible`), so a sealed-and-not-session-unlocked meeting
/// contributes NO row (aggregate posture) — same gate as `get_analytics` / `list_open_commitments`.
#[tauri::command]
pub fn list_meeting_action_summaries(
    state: State<'_, AppState>,
) -> Result<Vec<MeetingActionSummary>, AppError> {
    let unlocked = unlocked_snapshot(state.inner())?;
    state.db.list_meeting_action_summaries(&unlocked)
}

/// Run a recipe prompt over a meeting's transcript (grounded), returning the artifact text.
#[tauri::command]
pub async fn run_recipe(
    state: State<'_, AppState>,
    meeting_id: String,
    prompt: String,
) -> Result<String, AppError> {
    if prompt.trim().is_empty() {
        return Err(AppError::InvalidArg("recipe prompt is empty".into()));
    }
    // BLK-2b READ-GATE: a sealed-and-not-unlocked meeting's transcript is blanked; refuse to run a
    // recipe over it (would feed a cloud provider blank/garbage and depend on at-rest blanking).
    if !meeting_is_unlocked(state.inner(), &meeting_id)? {
        return Err(AppError::Locked(
            "this meeting's folder is locked — unlock it to run a recipe".into(),
        ));
    }
    let segments = state.db.get_segments(&meeting_id)?;
    if segments.is_empty() {
        return Err(AppError::InvalidArg(
            "this meeting has no transcript yet".into(),
        ));
    }
    let transcript = segments
        .iter()
        .map(|s| s.text.trim())
        .filter(|t| !t.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    let config = {
        state
            .config
            .lock()
            .map_err(|_| AppError::Config("config mutex poisoned".into()))?
            .clone()
    };
    let provider = crate::summarize::provider_for(crate::summarize::roles::Role::Notes, &config, &state.heavy_inference)?;
    let (system, user) =
        crate::summarize::recipes::build_recipe_prompt(&transcript, &prompt, &config.note_language);
    provider.complete(&system, &user).await
}

/// Parse a meeting note's "## Action items" checklist into structured items.
#[tauri::command]
pub fn get_action_items(
    state: State<'_, AppState>,
    meeting_id: String,
) -> Result<Vec<ActionItem>, AppError> {
    // D4 READ-GATE: a sealed-and-not-unlocked meeting's note markdown is blanked; refuse to parse
    // action items from it (would silently return none / leak a stale plaintext). Fail closed.
    if !meeting_is_unlocked(state.inner(), &meeting_id)? {
        return Err(AppError::Locked(
            "this meeting's folder is locked — unlock it to see action items".into(),
        ));
    }
    let note = state.db.get_latest_note_for_meeting(&meeting_id)?;
    Ok(match note {
        Some(n) => crate::summarize::action_items::parse_action_items(&n.markdown),
        None => Vec::new(),
    })
}

/// OPEN-COMMITMENTS rollup ("what did I promise / what's still open"): deterministically aggregate
/// every OPEN (`- [ ]`) action item across the VISIBLE library, with each item's meeting context.
/// No model — pure aggregation over the gated readers. `owner` (optional) filters case-insensitively.
/// GATED: routes through `Db::list_open_commitments`, which pushes the LIVE session unlock set
/// through `list_meetings_visible` + `get_note_if_visible` (the same predicate as `ask_vault` /
/// `generate_digest` / MCP) — a sealed-and-not-session-unlocked meeting contributes nothing.
#[tauri::command]
pub fn list_open_commitments(
    state: State<'_, AppState>,
    owner: Option<String>,
) -> Result<Vec<Commitment>, AppError> {
    let unlocked = unlocked_snapshot(state.inner())?;
    let owner = owner.as_deref().map(str::trim).filter(|o| !o.is_empty());
    state.db.list_open_commitments(&unlocked, owner)
}

/// Rewrite the note's action items into Obsidian Tasks format (📅 due dates) + re-write the
/// vault file in place. Returns the updated note.
#[tauri::command]
pub fn patch_note_tasks(
    state: State<'_, AppState>,
    meeting_id: String,
) -> Result<NoteDto, AppError> {
    // BLK-1 / TOCTOU (2026-07-10 audit F4): hold the lifecycle guard across gate+write so a
    // concurrent relock/seal cannot land between the unlock check and the upsert.
    let _lifecycle = lifecycle_guard(state.inner());
    // D4 WRITE-GATE: refuse to rewrite a sealed-and-not-unlocked meeting's note (its plaintext is
    // blanked; patching would persist the blanked value over the sealed content). Fail closed.
    if !meeting_is_unlocked(state.inner(), &meeting_id)? {
        return Err(AppError::Locked(
            "this meeting's folder is locked — unlock it to rewrite the note's tasks".into(),
        ));
    }
    let existing = state
        .db
        .get_latest_note_for_meeting(&meeting_id)?
        .ok_or_else(|| AppError::InvalidArg(format!("no note for meeting {meeting_id}")))?;
    let patched = crate::summarize::action_items::patch_tasks_markdown(&existing.markdown);
    let created_at = chrono::Utc::now().to_rfc3339();
    // Seal-on-write (audit F1): a session-unlocked LOCKED folder re-seals the patched markdown.
    upsert_note_reseal_if_locked(
        state.inner(),
        &NoteRecord {
            meeting_id: meeting_id.clone(),
            provider_id: existing.provider_id.clone(),
            markdown: patched.clone(),
            created_at,
            exported_path: existing.exported_path.clone(),
            model_requested: existing.model_requested.clone(),
            model_served: existing.model_served.clone(),
            gateway_host: existing.gateway_host.clone(),
        },
    )?;
    if let Some(path) = existing.exported_path.as_deref() {
        crate::export::overwrite_note(std::path::Path::new(path), &patched)?;
    }
    Ok(NoteDto {
        meeting_id,
        provider_id: existing.provider_id,
        markdown: patched,
        exported_path: existing.exported_path,
    })
}

/// Escape a string for embedding inside an AppleScript `"…"` literal: backslash + double-quote are
/// escaped, and raw CR/LF are flattened to spaces (an AppleScript string literal cannot span lines).
/// This is what stops the item text from breaking out of the quoted literal or injecting extra
/// statements (`"`, `end tell`, …) into the osascript program.
fn escape_applescript(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace(['\n', '\r'], " ")
}

/// Parse a strict ISO `YYYY-MM-DD` into `(year, month, day)`; `None` for anything else.
fn parse_iso_ymd(s: &str) -> Option<(i32, u32, u32)> {
    let s = s.trim();
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return None;
    }
    let y: i32 = s.get(0..4)?.parse().ok()?;
    let m: u32 = s.get(5..7)?.parse().ok()?;
    let d: u32 = s.get(8..10)?.parse().ok()?;
    if !(1..=12).contains(&m) || !(1..=31).contains(&d) {
        return None;
    }
    Some((y, m, d))
}

/// Build the osascript program that creates a Reminder named `name`. When `due_date` is a valid
/// ISO `YYYY-MM-DD`, attach `remind me date`/`due date` (defaulted to 9am local) so the date
/// actually lands in Reminders — previously the date was dropped. The name is
/// `escape_applescript`-escaped so its text can never break out of the string literal. The date is
/// built by setting `day` to 1 FIRST (so a year/month change can't overflow the current day-of-month),
/// then year, then month, then the real day.
pub(crate) fn build_reminder_script(name: &str, due_date: Option<&str>) -> String {
    let esc = escape_applescript(name);
    match due_date.and_then(parse_iso_ymd) {
        Some((y, m, d)) => format!(
            "set theDate to current date\n\
             set day of theDate to 1\n\
             set year of theDate to {y}\n\
             set month of theDate to {m}\n\
             set day of theDate to {d}\n\
             set hours of theDate to 9\n\
             set minutes of theDate to 0\n\
             set seconds of theDate to 0\n\
             tell application \"Reminders\" to make new reminder with properties {{name:\"{esc}\", remind me date:theDate, due date:theDate}}"
        ),
        None => format!(
            "tell application \"Reminders\" to make new reminder with properties {{name:\"{esc}\"}}"
        ),
    }
}

/// Add a macOS Reminder (via osascript) for an action item. A denied Reminders permission
/// surfaces a clear, actionable error rather than crashing the UI. When the item carries an ISO
/// due date, it is set as the reminder's due/remind date (best-effort; verify on a real Mac).
#[tauri::command]
pub async fn add_reminder(text: String, due_date: Option<String>) -> Result<(), AppError> {
    let name = text.trim().to_string();
    if name.is_empty() {
        return Err(AppError::InvalidArg("empty reminder".into()));
    }
    let due = due_date.as_deref().filter(|d| !d.is_empty());
    let script = build_reminder_script(&name, due);
    let out = tokio::task::spawn_blocking(move || {
        std::process::Command::new("osascript")
            .arg("-e")
            .arg(&script)
            .output()
    })
    .await
    .map_err(|e| AppError::Unavailable(format!("reminder task failed: {e}")))?
    .map_err(|e| AppError::Unavailable(format!("osascript failed: {e}")))?;
    if out.status.success() {
        Ok(())
    } else {
        Err(AppError::Unavailable(format!(
            "Could not add to Reminders — grant access in System Settings ▸ Privacy & Security ▸ Reminders. ({})",
            String::from_utf8_lossy(&out.stderr).trim()
        )))
    }
}

/// SYNCHRONOUS reminder creation for the off-thread voice-action dispatch (Flow B). Mirrors the
/// `add_reminder` command's osascript path, but blocking (it already runs on a detached task, so it
/// must not require an async runtime). Returns `Ok(())` on success, a typed `AppError` otherwise —
/// NEVER panics. NO PII logged by the caller; the reminder text is the user's own dictated note.
pub(crate) fn add_reminder_blocking(text: &str, due_date: Option<&str>) -> Result<(), AppError> {
    let name = text.trim();
    if name.is_empty() {
        return Err(AppError::InvalidArg("empty reminder".into()));
    }
    let due = due_date.filter(|d| !d.is_empty());
    let script = build_reminder_script(name, due);
    let out = std::process::Command::new("osascript")
        .arg("-e")
        .arg(&script)
        .output()
        .map_err(|e| AppError::Unavailable(format!("osascript failed: {e}")))?;
    if out.status.success() {
        Ok(())
    } else {
        Err(AppError::Unavailable(format!(
            "Could not add to Reminders — grant access in System Settings ▸ Privacy & Security ▸ Reminders. ({})",
            String::from_utf8_lossy(&out.stderr).trim()
        )))
    }
}

/// Pin a meeting moment: append a timestamped ^block-ref to the note (DB + vault file) and
/// return an obsidian:// deep link to the note.
#[tauri::command]
pub fn pin_moment(
    state: State<'_, AppState>,
    meeting_id: String,
    seconds: f64,
    label: String,
) -> Result<PinResult, AppError> {
    // BLK-1 / TOCTOU (2026-07-10 audit F4): hold the lifecycle guard across gate+write so a
    // concurrent relock/seal cannot land between the unlock check and the upsert.
    let _lifecycle = lifecycle_guard(state.inner());
    // BLK-2b WRITE-GATE: refuse to pin into a sealed-and-not-unlocked meeting's note — its plaintext
    // markdown is blanked, so appending a pin would persist the blanked value over the sealed
    // content AND re-export a plaintext `.md`. Fail closed.
    if !meeting_is_unlocked(state.inner(), &meeting_id)? {
        return Err(AppError::Locked(
            "this meeting's folder is locked — unlock it to pin a moment".into(),
        ));
    }
    let existing = state
        .db
        .get_latest_note_for_meeting(&meeting_id)?
        .ok_or_else(|| AppError::InvalidArg(format!("no note for meeting {meeting_id}")))?;
    let secs = seconds.max(0.0) as i64;
    let block_id = format!("m{secs}");
    let mmss = format!("{}:{:02}", secs / 60, secs % 60);
    let new_md = crate::export::append_pin(&existing.markdown, &mmss, &label, &block_id);
    let created_at = chrono::Utc::now().to_rfc3339();
    // Seal-on-write (audit F1): a session-unlocked LOCKED folder re-seals the pinned markdown.
    upsert_note_reseal_if_locked(
        state.inner(),
        &NoteRecord {
            meeting_id: meeting_id.clone(),
            provider_id: existing.provider_id.clone(),
            markdown: new_md.clone(),
            created_at,
            exported_path: existing.exported_path.clone(),
            model_requested: existing.model_requested.clone(),
            model_served: existing.model_served.clone(),
            gateway_host: existing.gateway_host.clone(),
        },
    )?;
    let url = match existing.exported_path.as_deref() {
        Some(path) => {
            crate::export::overwrite_note(std::path::Path::new(path), &new_md)?;
            let vault = {
                state
                    .config
                    .lock()
                    .map_err(|_| AppError::Config("config mutex poisoned".into()))?
                    .vault_path
                    .clone()
            };
            match vault.as_deref().filter(|p| !p.is_empty()) {
                Some(v) => crate::export::build_open_url(
                    std::path::Path::new(v),
                    std::path::Path::new(path),
                ),
                None => String::new(),
            }
        }
        None => String::new(),
    };
    Ok(PinResult {
        url,
        block_id,
        mmss,
    })
}

/// Extract the people + projects from a meeting note and persist them through the dual-sink:
///
/// - **Sink A (always):** upsert each entity into the encrypted DB (`upsert_entity`, case-
///   insensitive dedup) and record a mention (`add_mention`, idempotent). The DB is the
///   source of truth for the in-app graph and works with NO vault configured.
/// - **Sink B (gated):** mirror each entity as a `[[ ]]` vault stub via `ensure_entity_backlink`
///   ONLY when a vault is configured AND the meeting's folder is NOT locked (`folder_by_id`
///   disk-truth — NOT session unlock). A session-unlocked folder must NOT re-emit `.md` stubs
///   (they were removed on seal and stay out until a permanent remove-lock), so the write gate
///   uses `locked` while every READ uses `unlocked`. A meeting at the vault root (no folder)
///   has no lock and gets its stubs.
///
/// Returns the extracted `GraphPayload`. The caller decides whether extraction failures are fatal
/// (the `link_meeting_entities` command surfaces them; the pipeline hook swallows them).
pub async fn build_and_persist_entities(
    app: &AppHandle,
    state: &AppState,
    meeting_id: &str,
    title: &str,
    markdown: &str,
) -> Result<crate::summarize::graph::GraphPayload, AppError> {
    let config = {
        state
            .config
            .lock()
            .map_err(|_| AppError::Config("config mutex poisoned".into()))?
            .clone()
    };
    let provider = crate::summarize::provider_for(crate::summarize::roles::Role::Notes, &config, &state.heavy_inference)?;
    let entities_started = std::time::Instant::now();
    let payload =
        crate::summarize::graph::extract_entities(provider.as_ref(), title, markdown).await?;
    tracing::info!(
        target: "perf",
        stage = "extract_entities",
        elapsed_ms = entities_started.elapsed().as_millis() as u64,
        "pipeline stage complete"
    );

    // Sink A — ALWAYS persist to the encrypted DB (the graph's source of truth). Collect the
    // resolved (entity_id, name) pairs so the bitemporal-facts pass below can extract + reconcile
    // facts ABOUT these very entities.
    let mut entity_refs: Vec<(String, String)> = Vec::new();
    for p in &payload.people {
        let id = state
            .db
            .upsert_entity(p, crate::storage::models::EntityKind::Person)?;
        state.db.add_mention(&id, meeting_id)?;
        entity_refs.push((id, p.clone()));
    }
    for pr in &payload.projects {
        let id = state
            .db
            .upsert_entity(pr, crate::storage::models::EntityKind::Project)?;
        state.db.add_mention(&id, meeting_id)?;
        entity_refs.push((id, pr.clone()));
    }

    // brain2 R2 — BITEMPORAL FACTS + Phase 3 CROSS-MEETING USER MEMORY. Both are BEST-EFFORT +
    // NEVER fail the note: extract entity·predicate·object / user-preference candidates via the
    // on-device reasoner (empty with the stub / no model), reconcile, apply in one tx each. A
    // reconcile/extract hiccup is logged (non-PII) and swallowed EITHER WAY — that part is
    // unchanged. What changed: the reasoner dispatch (the brain sidecar, up to the hard-cap
    // timeout — currently 180s) used to run INLINE on this async command's Tokio worker, TWICE
    // per meeting, on EVERY recording Stop (2026-07-13 perf audit, HIGH severity). Moved to the
    // blocking pool via `perf::run_heavy` (serializes against other heavy native calls too), using
    // the AppHandle re-fetch pattern (`State<'_, AppState>` can't be captured by a `'static`
    // closure). Both calls already catch + log their own errors internally, so the closure always
    // returns `Ok(())` — a join-panic from `run_heavy` itself is logged and swallowed the same way,
    // preserving the exact "never fail the note" contract.
    let app_for_facts = app.clone();
    let meeting_id_owned = meeting_id.to_string();
    let title_owned = title.to_string();
    let markdown_owned = markdown.to_string();
    let entity_refs_owned = entity_refs.clone();
    let facts_started = std::time::Instant::now();
    if let Err(e) = crate::perf::run_heavy(&state.heavy_inference, move || -> Result<(), AppError> {
        let state = app_for_facts.state::<AppState>();
        let t0 = std::time::Instant::now();
        if let Err(e) = persist_facts_for_meeting(
            &state,
            &meeting_id_owned,
            &title_owned,
            &markdown_owned,
            &entity_refs_owned,
        ) {
            tracing::warn!(target: "facts", error = %e, "fact reconcile failed (note unaffected)");
        }
        tracing::info!(target: "perf", stage = "persist_facts", elapsed_ms = t0.elapsed().as_millis() as u64, "pipeline stage complete");
        let t1 = std::time::Instant::now();
        if let Err(e) =
            persist_user_facts_for_meeting(&state, &meeting_id_owned, &title_owned, &markdown_owned)
        {
            tracing::warn!(target: "user_memory", error = %e, "user-fact reconcile failed (note unaffected)");
        }
        tracing::info!(target: "perf", stage = "persist_user_facts", elapsed_ms = t1.elapsed().as_millis() as u64, "pipeline stage complete");
        Ok(())
    })
    .await
    {
        tracing::warn!(target: "facts", error = %e, "facts/user-memory blocking task failed (note unaffected)");
    }
    tracing::info!(
        target: "perf",
        stage = "facts_and_user_memory_total",
        elapsed_ms = facts_started.elapsed().as_millis() as u64,
        "pipeline stage complete"
    );

    // Sink B — vault [[ ]] stubs, ONLY when a vault is configured AND the meeting's folder is
    // NOT sealed on disk. Disk-truth `locked` (not session `unlocked`): a session-unlock must
    // never re-write encrypted-content stubs back to plaintext on disk.
    let vault = config.vault_path.clone().filter(|p| !p.is_empty());
    if let Some(vault) = vault {
        let folder_locked = match state.db.get_meeting(meeting_id)?.and_then(|m| m.folder_id) {
            Some(folder_id) => state
                .db
                .folder_by_id(&folder_id)?
                .map(|f| f.locked)
                .unwrap_or(false),
            None => false, // vault root → never locked
        };
        if !folder_locked {
            let vault_path = std::path::Path::new(&vault);
            for p in &payload.people {
                crate::export::entity_stub::ensure_entity_backlink(vault_path, "People", p, title)?;
            }
            for pr in &payload.projects {
                crate::export::entity_stub::ensure_entity_backlink(
                    vault_path, "Projects", pr, title,
                )?;
            }
        }
    }

    Ok(payload)
}

/// brain2 R2 — extract → reconcile → apply bitemporal FACTS for one summarized meeting. Pulled out
/// of [`build_and_persist_entities`] so it can fail in isolation (its caller logs + swallows): a
/// facts hiccup must NEVER block the note pipeline. Steps:
///   1. BEST-EFFORT extract candidates from the note about `entity_refs` (empty with the stub/no
///      model — the deterministic core is what carries the value),
///   2. load the EXISTING facts for those entities (un-gated lifecycle read),
///   3. run the PURE deterministic [`crate::facts::reconcile_facts`] at the meeting's time,
///   4. stamp the source meeting onto the Add ops and apply them in ONE atomic tx.
///
/// `at` is the meeting's `started_at` (the fact's valid-time origin), falling back to now.
fn persist_facts_for_meeting(
    state: &AppState,
    meeting_id: &str,
    title: &str,
    markdown: &str,
    entity_refs: &[(String, String)],
) -> Result<(), AppError> {
    if entity_refs.is_empty() {
        return Ok(());
    }
    // 1) Best-effort extraction (panic-free, empty on stub/no model/decode failure). The reasoner
    //    is re-resolved from the LIVE config, so a consent/backend change applies without restart.
    let candidates = crate::facts::extract_fact_candidates(
        // Brain Live ON ⇒ the LOCAL light engine (facts stop egressing); OFF ⇒ today's Notes reasoner.
        &*state.reasoner.extraction_reasoner(),
        title,
        markdown,
        entity_refs,
        // Post-call extraction over the full note: no tight cap (the realtime path uses a capped preset).
        crate::reason::GenOptions::default(),
    );
    if candidates.is_empty() {
        return Ok(()); // nothing to reconcile — common in the default (no-model) build.
    }
    // 2) Existing facts for exactly these entities.
    let entity_ids: Vec<String> = entity_refs.iter().map(|(id, _)| id.clone()).collect();
    let existing = state.db.facts_for_entities(&entity_ids)?;
    // 3) Deterministic reconcile at the meeting's time (valid-time origin).
    let at = state
        .db
        .get_meeting(meeting_id)?
        .map(|m| m.started_at)
        .unwrap_or_else(|| chrono::Utc::now().to_rfc3339());
    let mut ops = crate::facts::reconcile_facts(&existing, &candidates, &at);
    // 4) Stamp the source meeting (gating + purge anchor) and apply atomically.
    crate::facts::set_meeting_id(&mut ops, meeting_id);
    state.db.apply_fact_ops(&ops)?;
    // Re-Truth (the vault heals itself): capture SUPERSESSIONS — every Invalidate that closed a fact
    // sourced in an OLDER meeting is recorded for one-tap review + stamping. BEST-EFFORT and NEVER
    // fails the note: a hiccup is logged (non-PII: counts only) and swallowed, exactly like the facts
    // hook that wraps this whole fn.
    if let Err(e) = record_supersessions_for_meeting(state, meeting_id, &existing, &ops) {
        tracing::warn!(target: "retruth", error = %e, "supersession capture failed (facts unaffected)");
    }
    Ok(())
}

/// Re-Truth: derive + persist the supersessions for one reconcile batch (called after
/// `apply_fact_ops`). Best-effort; returns `Ok` with nothing recorded when there are no cross-note
/// supersessions. Non-PII log line (a count only).
fn record_supersessions_for_meeting(
    state: &AppState,
    superseding_meeting_id: &str,
    existing: &[crate::facts::Fact],
    ops: &[crate::facts::FactOp],
) -> Result<(), AppError> {
    let now = chrono::Utc::now().to_rfc3339();
    let rows = build_supersession_rows(superseding_meeting_id, existing, ops, &now);
    if rows.is_empty() {
        return Ok(());
    }
    let recorded = state.db.record_supersessions(&rows)?;
    if recorded > 0 {
        tracing::info!(target: "retruth", recorded, "supersessions captured for review");
    }
    Ok(())
}

/// PURE (no DB, no clock — `now` injected): build the SUPERSESSION rows for one reconcile batch. For
/// each `FactOp::Invalidate` (which closed an OLD fact), resolve that old fact in `existing`
/// (entity/predicate/old_value + its source meeting) and the matching `FactOp::Add` (the new value
/// that superseded it, same entity+subject+predicate key reconcile used). SKIPS: an Invalidate whose
/// old fact is absent or has no source meeting, a self-supersession (the older fact came from the SAME
/// meeting), or a change with no matching Add. Deterministic + headless-testable.
fn build_supersession_rows(
    superseding_meeting_id: &str,
    existing: &[crate::facts::Fact],
    ops: &[crate::facts::FactOp],
    now: &str,
) -> Vec<crate::storage::models::SupersessionRow> {
    use crate::facts::FactOp;
    let norm = |s: &str| s.trim().to_lowercase();
    let mut out = Vec::new();
    for op in ops {
        let FactOp::Invalidate { id, .. } = op else {
            continue;
        };
        let Some(old) = existing.iter().find(|f| &f.id == id) else {
            continue;
        };
        let Some(source) = old.meeting_id.as_deref().filter(|m| !m.is_empty()) else {
            continue; // legacy/unattributed old fact — no source note to stamp.
        };
        if source == superseding_meeting_id {
            continue; // a meeting refining its own earlier fact is not a cross-note supersession.
        }
        // The new value is the Add op sharing the old fact's (entity_id, subject, predicate) key.
        let Some(new_value) = ops.iter().find_map(|o| match o {
            FactOp::Add(nf)
                if nf.entity_id == old.entity_id
                    && norm(&nf.subject) == norm(&old.subject)
                    && norm(&nf.predicate) == norm(&old.predicate) =>
            {
                Some(nf.object.clone())
            }
            _ => None,
        }) else {
            continue;
        };
        out.push(crate::storage::models::SupersessionRow {
            id: uuid::Uuid::new_v4().to_string(),
            superseding_meeting_id: superseding_meeting_id.to_string(),
            source_meeting_id: source.to_string(),
            entity: old.subject.clone(),
            predicate: old.predicate.clone(),
            old_value: old.object.clone(),
            new_value,
            created_at: now.to_string(),
            applied_at: None,
            source_pre_image: None,
            superseding_pre_image: None,
        });
    }
    out
}

/// Phase 3 CROSS-MEETING USER MEMORY — extract → reconcile → apply USER-SCOPED facts for one
/// summarized meeting. Mirrors [`persist_facts_for_meeting`] but for the user, not entities:
///   1. BEST-EFFORT extract user·predicate·object candidates from the note + the user's own typed
///      notes (empty with the stub / no model — the deterministic core is what carries the value),
///   2. load the EXISTING user facts (un-gated lifecycle read — reconcile runs before any seal),
///   3. run the PURE deterministic [`crate::facts::reconcile_facts`] at the meeting's time (the
///      user-scope sentinel in `entity_id` keys the reconcile),
///   4. stamp the source meeting onto the Add ops and apply them to `user_facts` in ONE atomic tx.
///
/// The (derived) memory brief is regenerated lazily on the next read/turn — no cache to invalidate.
fn persist_user_facts_for_meeting(
    state: &AppState,
    meeting_id: &str,
    title: &str,
    markdown: &str,
) -> Result<(), AppError> {
    // FLAG: when the user has turned cross-meeting memory OFF, skip extraction ENTIRELY — no
    // reasoner call, no candidates, nothing new persisted. (Existing facts stay; the user can
    // forget/clear them, and the gated reads/injection are separately flag-suppressed.)
    if !user_memory_enabled(state) {
        return Ok(());
    }
    // The user's OWN typed notes for this meeting are a high-signal memory source (an explicit
    // "remember that…"). Empty when none (best-effort read).
    let typed_notes = state.db.get_manual_notes(meeting_id).unwrap_or_default();
    // D5 — the meeting's own @brain THREAD TURNS are the HIGHEST-signal source (an explicit
    // "zapamiętaj, że…" in a thread). GATED like every content read: the just-finished meeting is
    // its own unlocked meeting, so `list_assistant_interactions_visible` under the live unlock
    // snapshot returns its turns (and NOTHING for a sealed-not-unlocked meeting — fail-closed). We
    // feed the USER COMMAND text (the high-signal part), never the assistant's answer.
    let thread_turns = gated_meeting_thread_turns(state, meeting_id);
    // 1) Best-effort extraction (panic-free, empty on stub/no model/decode failure). The reasoner is
    //    re-resolved from the LIVE config so a consent/backend change applies without restart.
    let candidates = crate::user_memory::extract_user_fact_candidates(
        // Brain Live ON ⇒ the LOCAL light engine (user facts stop egressing); OFF ⇒ today's reasoner.
        &*state.reasoner.extraction_reasoner(),
        title,
        markdown,
        &typed_notes,
        &thread_turns,
    );
    if candidates.is_empty() {
        return Ok(()); // nothing to reconcile — common in the default (no-model) build.
    }
    // 2) Existing user facts (all of them — the reconcile input).
    let existing = state.db.user_facts_all()?;
    // 3) Deterministic reconcile at the meeting's time (valid-time origin).
    let at = state
        .db
        .get_meeting(meeting_id)?
        .map(|m| m.started_at)
        .unwrap_or_else(|| chrono::Utc::now().to_rfc3339());
    let mut ops = crate::facts::reconcile_facts(&existing, &candidates, &at);
    // 4) Stamp the source meeting (gating + purge anchor) and apply atomically.
    crate::facts::set_meeting_id(&mut ops, meeting_id);
    state.db.apply_user_fact_ops(&ops)?;
    Ok(())
}

/// Whether cross-meeting USER MEMORY is enabled (config `user_memory_enabled`, default TRUE). When
/// OFF: no extraction runs, no brief is injected into ANY surface, and `get_user_memory` reports the
/// disabled marker. Fail-safe: a poisoned config mutex reports ENABLED (the default) so a transient
/// lock error never silently disables the feature.
fn user_memory_enabled(state: &AppState) -> bool {
    state
        .config
        .lock()
        .map(|c| c.user_memory_enabled)
        .unwrap_or(true)
}

// ── Re-Truth (the vault heals itself) — supersession review + one-tap stamp ──────────────────────

/// One supersession surfaced for review (camelCase for the FE). `sourceNotePath` is the absolute
/// on-disk `.md` the FE never shows (it shows `sourceNoteTitle`); `applied` reflects whether the
/// row has already been stamped (always `false` from `preview_supersessions`, which returns the
/// pending set).
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SupersessionDto {
    pub id: String,
    pub entity: String,
    pub predicate: String,
    pub old_value: String,
    pub new_value: String,
    pub source_note_title: String,
    pub source_note_path: String,
    pub source_meeting_id: String,
    pub superseding_meeting_id: String,
    /// The superseding note's title — `None` when that note is sealed (never leak a locked title).
    pub superseding_note_title: Option<String>,
    pub applied: bool,
}

/// Result of `apply_supersessions`: how many were stamped vs skipped because their source note sealed
/// (or lost its vault file) between preview and apply (the prune↔seal TOCTOU discipline).
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ApplyResult {
    pub applied: usize,
    pub skipped_sealed: usize,
}

/// A source note is STAMPABLE iff it is BOTH session-unlocked (content-read gate) AND its folder is
/// NOT locked-on-disk (write-safety gate). A sealed source's `.md` was deleted on seal and its facts
/// must surface nothing, so the intersection excludes any locked-or-not-unlocked source — Re-Truth v1
/// only ever touches OPEN-folder notes.
fn source_is_stampable(state: &AppState, meeting_id: &str) -> Result<bool, AppError> {
    Ok(meeting_is_unlocked(state, meeting_id)? && !folder_locked_on_disk(state, meeting_id)?)
}

/// Whether a meeting's folder is sealed ON DISK (disk-truth `locked`, NOT session unlock). Mirrors the
/// `build_and_persist_entities` write gate: a meeting at the vault root (no folder) is never locked.
fn folder_locked_on_disk(state: &AppState, meeting_id: &str) -> Result<bool, AppError> {
    match state.db.folder_for_meeting(meeting_id)? {
        Some(fid) => Ok(state
            .db
            .folder_by_id(&fid)?
            .map(|f| f.locked)
            .unwrap_or(false)),
        None => Ok(false),
    }
}

/// Resolve a meeting's on-disk note file: `(absolute .md path, file-stem title)` from the latest note
/// row's `exported_path`. `None` when the meeting has no note or was never exported to the vault (so
/// there is nothing to stamp). RAW read — callers gate on the meeting BEFORE exposing the result.
fn note_file_for(state: &AppState, meeting_id: &str) -> Result<Option<(String, String)>, AppError> {
    let note = match state.db.get_latest_note_for_meeting(meeting_id)? {
        Some(n) => n,
        None => return Ok(None),
    };
    let path = match note.exported_path {
        Some(p) if !p.trim().is_empty() => p,
        _ => return Ok(None),
    };
    let stem = std::path::Path::new(&path)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("")
        .to_string();
    Ok(Some((path, stem)))
}

/// Preview the PENDING supersessions whose superseding meeting is `meeting_id`. GATED: a row is
/// included ONLY when its SOURCE meeting is stampable (open-on-disk + unlocked) AND has a vault `.md`;
/// a sealed-or-unexported source contributes NOTHING. The superseding note's title is surfaced only
/// when that note is itself unlocked. Returns `[]` when there are none.
#[tauri::command]
pub fn preview_supersessions(
    state: State<'_, AppState>,
    meeting_id: String,
) -> Result<Vec<SupersessionDto>, AppError> {
    preview_supersessions_inner(state.inner(), &meeting_id)
}

pub(crate) fn preview_supersessions_inner(
    state: &AppState,
    meeting_id: &str,
) -> Result<Vec<SupersessionDto>, AppError> {
    let rows = state.db.unapplied_supersessions_for(meeting_id)?;
    let mut out = Vec::new();
    for r in rows {
        // GATE the SOURCE note (content-read + write-safety). A sealed/not-unlocked source is dropped.
        if !source_is_stampable(state, &r.source_meeting_id)? {
            continue;
        }
        // GATE the SUPERSEDING side TOO — defense-in-depth. `new_value` is derived from the superseding
        // meeting's fact, so a sealed-and-not-session-unlocked superseding meeting must surface NOTHING,
        // even in the brief race window where `lock_folder` has flipped `locked=1` but not yet purged
        // this row. Purge-on-seal normally removes it; this second-side gate closes the race regardless.
        if !meeting_is_unlocked(state, &r.superseding_meeting_id)? {
            continue;
        }
        let Some((path, stem)) = note_file_for(state, &r.source_meeting_id)? else {
            continue; // no vault file → nothing to stamp/show.
        };
        // The superseding meeting is now known-unlocked, so its title is safe to surface (`None` only
        // when it was never exported to the vault).
        let superseding_note_title =
            note_file_for(state, &r.superseding_meeting_id)?.map(|(_, s)| s);
        out.push(SupersessionDto {
            id: r.id,
            entity: r.entity,
            predicate: r.predicate,
            old_value: r.old_value,
            new_value: r.new_value,
            source_note_title: stem,
            source_note_path: path,
            source_meeting_id: r.source_meeting_id,
            superseding_meeting_id: r.superseding_meeting_id,
            superseding_note_title,
            applied: r.applied_at.is_some(),
        });
    }
    Ok(out)
}

/// APPLY the given supersessions: append a `[!superseded]` callout to each SOURCE note (and a mirror
/// backlink to the superseding note, when it too is open). RE-GATES each row at apply time — a source
/// that sealed since preview is SKIPPED (never stamped), the prune↔seal TOCTOU discipline. Snapshots
/// each note's exact bytes into the row's pre-image BEFORE the (append-only) write, so `undo` restores
/// them byte-identical. Idempotent: an already-applied row is a no-op, and the callout carries a
/// stable marker so re-stamping never duplicates.
#[tauri::command]
pub fn apply_supersessions(
    state: State<'_, AppState>,
    ids: Vec<String>,
) -> Result<ApplyResult, AppError> {
    apply_supersessions_inner(state.inner(), &ids)
}

pub(crate) fn apply_supersessions_inner(
    state: &AppState,
    ids: &[String],
) -> Result<ApplyResult, AppError> {
    let mut applied = 0usize;
    let mut skipped_sealed = 0usize;
    let date = chrono::Utc::now().format("%Y-%m-%d").to_string();

    // PER-BATCH PRISTINE CACHE, keyed by note FILE path. Multiple rows in ONE heal touch the SAME
    // note — every row shares the superseding meeting's note, and two facts from one old note share a
    // SOURCE note too. The undo pre-image for a file MUST be its PRE-BATCH ("pristine") content,
    // captured the FIRST time this call touches that path — never the mid-batch, already-stamped
    // bytes a later row would otherwise read. So all rows sharing a note carry IDENTICAL pristine
    // pre-images and undo (restore-each-file-once) is order-independent + byte-identical for N≥2.
    let mut pristine: std::collections::HashMap<String, Vec<u8>> = std::collections::HashMap::new();

    // PRE-PASS: seed the cache from any pre-images ALREADY durably stored by an earlier (crashed)
    // attempt, keyed by note path — so a row that still has to capture its pre-image finds the
    // pristine bytes here instead of re-reading a sibling-stamped file, regardless of the id order a
    // retry arrives in (retry-safe AND order-independent).
    for id in ids {
        let Some(row) = state.db.get_supersession(id)? else {
            continue;
        };
        if let Some(pre) = &row.source_pre_image {
            if let Some((path, _)) = note_file_for(state, &row.source_meeting_id)? {
                pristine.entry(path).or_insert_with(|| pre.clone());
            }
        }
        if let Some(pre) = &row.superseding_pre_image {
            if let Some((path, _)) = note_file_for(state, &row.superseding_meeting_id)? {
                pristine.entry(path).or_insert_with(|| pre.clone());
            }
        }
    }

    for id in ids {
        let Some(row) = state.db.get_supersession(id)? else {
            continue; // unknown id — nothing to do.
        };
        if row.applied_at.is_some() {
            continue; // already stamped — idempotent no-op.
        }
        // TOCTOU re-gate: the source folder may have sealed since preview. A now-sealed/not-unlocked
        // (or unexported) source is SKIPPED, never stamped.
        if !source_is_stampable(state, &row.source_meeting_id)? {
            skipped_sealed += 1;
            continue;
        }
        let Some((source_path, source_stem)) = note_file_for(state, &row.source_meeting_id)? else {
            skipped_sealed += 1;
            continue;
        };

        // The superseding note gets a backlink ONLY when it is itself open-on-disk + unlocked (never
        // write into or reference a sealed note). Its stem feeds the source callout's `[[…]]` link.
        let superseding_open = meeting_is_unlocked(state, &row.superseding_meeting_id)?
            && !folder_locked_on_disk(state, &row.superseding_meeting_id)?;
        let superseding_file = if superseding_open {
            note_file_for(state, &row.superseding_meeting_id)?
        } else {
            None
        };

        // Resolve PRISTINE pre-images from the per-path cache (reads + UTF-8-validates each file on its
        // first batch-touch; every later row sharing the path reuses the SAME pristine bytes).
        let source_pre = pristine_note_bytes(&mut pristine, &source_path)?;
        let superseding_pre = match &superseding_file {
            Some((p, _)) => Some(pristine_note_bytes(&mut pristine, p)?),
            None => None,
        };

        // DURABLE-BEFORE-WRITE: persist the pristine pre-images BEFORE any `.md` write, so a crash
        // between write and mark-applied still leaves a recoverable un-stamped pre-image. `COALESCE`
        // never clobbers an already-stored pristine backup and, combined with the pristine cache, the
        // stored bytes are NEVER a re-snapshot of a stamped file.
        state.db.store_supersession_pre_images(
            id,
            Some(&source_pre),
            superseding_pre.as_deref(),
        )?;

        // Stamp the SOURCE note: append the callout to the CURRENT on-disk content (idempotent — a
        // retry over an already-stamped file is a no-op). The undo pre-image is the pristine cache
        // copy, never these current bytes.
        let current_source = std::fs::read_to_string(&source_path)
            .map_err(|e| AppError::Export(format!("read source note failed: {e}")))?;
        let new_source = crate::export::obsidian::append_supersession_callout(
            &current_source,
            &date,
            &row.predicate,
            &row.old_value,
            &row.new_value,
            superseding_file.as_ref().map(|(_, s)| s.as_str()),
        );
        crate::export::obsidian::overwrite_note(std::path::Path::new(&source_path), &new_source)?;

        // Stamp the SUPERSEDING backlink (its pristine pre-image is now durably stored). Append to its
        // CURRENT content (idempotent).
        if let Some((sup_path, _)) = &superseding_file {
            let current_sup = std::fs::read_to_string(sup_path)
                .map_err(|e| AppError::Export(format!("read superseding note failed: {e}")))?;
            let new_sup = crate::export::obsidian::append_supersedes_callout(
                &current_sup,
                &date,
                &row.predicate,
                &row.old_value,
                &row.new_value,
                &source_stem,
            );
            crate::export::obsidian::overwrite_note(std::path::Path::new(sup_path), &new_sup)?;
        }

        // APPLIED is the LAST write — flipped only after the note(s) are safely stamped.
        state
            .db
            .mark_supersession_applied(id, &chrono::Utc::now().to_rfc3339())?;
        applied += 1;
    }
    tracing::info!(target: "retruth", applied, skipped_sealed, "supersessions applied");
    Ok(ApplyResult {
        applied,
        skipped_sealed,
    })
}

/// Resolve the PRISTINE (pre-batch) bytes of a note file from the per-apply-call cache: on the first
/// touch of a path this batch, read + UTF-8-validate the file and cache it; every later touch reuses
/// the cached bytes. This is what makes all rows sharing a note carry identical pristine pre-images
/// (so a multi-row undo restores each file once, byte-identical). Refusing a non-UTF-8 file here —
/// before any write — keeps the stamp all-or-nothing.
fn pristine_note_bytes(
    cache: &mut std::collections::HashMap<String, Vec<u8>>,
    path: &str,
) -> Result<Vec<u8>, AppError> {
    if let Some(b) = cache.get(path) {
        return Ok(b.clone());
    }
    let bytes =
        std::fs::read(path).map_err(|e| AppError::Export(format!("read note failed: {e}")))?;
    String::from_utf8(bytes.clone())
        .map_err(|_| AppError::Export("note is not valid UTF-8".into()))?;
    cache.insert(path.to_string(), bytes.clone());
    Ok(bytes)
}

/// UNDO the given applied supersessions: restore each stamped note's byte-exact pre-image (atomic
/// overwrite) and clear the row's applied state + pre-images. A row that isn't applied is a no-op. A
/// note whose folder sealed since apply is SKIPPED (never re-materialize plaintext into a locked
/// folder) — the sealed content will return WITH the stamp on unlock.
#[tauri::command]
pub fn undo_supersessions(state: State<'_, AppState>, ids: Vec<String>) -> Result<(), AppError> {
    undo_supersessions_inner(state.inner(), &ids)
}

pub(crate) fn undo_supersessions_inner(state: &AppState, ids: &[String]) -> Result<(), AppError> {
    let undo_set: std::collections::HashSet<&str> = ids.iter().map(String::as_str).collect();

    // Collect the DISTINCT affected note files touched by the UNDO SET (`path -> (meeting_id,
    // pristine pre-image)`). All rows in one heal sharing a note carry IDENTICAL pristine pre-images
    // (see apply's per-path cache), and `path ↔ meeting` is 1:1. Only files whose folder is still
    // OPEN are collected/rewritten (never re-materialize plaintext into a sealed folder — a sealed
    // note's stamp rides inside its sealed content already; and purge-on-seal has already dropped any
    // supersession referencing a sealed meeting).
    let mut affected: std::collections::HashMap<String, (String, Vec<u8>)> =
        std::collections::HashMap::new();
    let mut to_clear: Vec<&String> = Vec::new();
    for id in ids {
        let Some(row) = state.db.get_supersession(id)? else {
            continue;
        };
        if row.applied_at.is_none() {
            continue; // nothing applied to undo.
        }
        if let Some(pre) = &row.source_pre_image {
            if !folder_locked_on_disk(state, &row.source_meeting_id)? {
                if let Some((path, _)) = note_file_for(state, &row.source_meeting_id)? {
                    affected
                        .entry(path)
                        .or_insert_with(|| (row.source_meeting_id.clone(), pre.clone()));
                }
            }
        }
        if let Some(pre) = &row.superseding_pre_image {
            if !folder_locked_on_disk(state, &row.superseding_meeting_id)? {
                if let Some((path, _)) = note_file_for(state, &row.superseding_meeting_id)? {
                    affected
                        .entry(path)
                        .or_insert_with(|| (row.superseding_meeting_id.clone(), pre.clone()));
                }
            }
        }
        to_clear.push(id);
    }

    // For each affected file: rebuild it as pristine + the stamps of every SURVIVOR — a supersession
    // that touches THIS note's meeting, is NOT in the undo set, and remains applied. Because the
    // callout appends are idempotent + order-independent across distinct supersessions, replaying the
    // survivors reconstructs the exact on-disk state that matches the DB. A FULL undo (no survivors)
    // collapses to a plain pristine restore. This closes the partial-undo desync where restoring a
    // shared file to pristine silently stripped a still-applied sibling's on-disk stamp.
    for (path, (meeting_id, pristine)) in &affected {
        let mut text = String::from_utf8(pristine.clone())
            .map_err(|_| AppError::Export("stored pre-image is not valid UTF-8".into()))?;
        for s in state.db.supersessions_touching_meeting(meeting_id)? {
            if undo_set.contains(s.id.as_str()) || s.applied_at.is_none() {
                continue; // being undone, or not currently applied → no stamp to replay.
            }
            // Reproduce this survivor's stamp with its ORIGINAL date (the day it was applied) so the
            // replay byte-matches the original append.
            let date = s
                .applied_at
                .as_deref()
                .and_then(|a| a.split('T').next())
                .unwrap_or("")
                .to_string();
            if &s.source_meeting_id == meeting_id {
                // This file is the SURVIVOR's SOURCE note → re-append its `[!superseded]` callout,
                // reproducing the `· see [[…]]` link exactly as apply did (open superseding only).
                let sup_stem = superseding_link_stem(state, &s)?;
                text = crate::export::obsidian::append_supersession_callout(
                    &text,
                    &date,
                    &s.predicate,
                    &s.old_value,
                    &s.new_value,
                    sup_stem.as_deref(),
                );
            }
            if &s.superseding_meeting_id == meeting_id {
                // This file is the SURVIVOR's SUPERSEDING note → re-append its `[!supersedes]`
                // backlink referencing the survivor's SOURCE stem.
                if let Some((_, src_stem)) = note_file_for(state, &s.source_meeting_id)? {
                    text = crate::export::obsidian::append_supersedes_callout(
                        &text,
                        &date,
                        &s.predicate,
                        &s.old_value,
                        &s.new_value,
                        &src_stem,
                    );
                }
            }
        }
        crate::export::obsidian::overwrite_note(std::path::Path::new(path), &text)?;
    }

    // Clear the applied state on the undone rows ONLY (pre-images dropped); survivors stay applied.
    for id in to_clear {
        state.db.clear_supersession_applied(id)?;
    }
    Ok(())
}

/// The `· see [[stem]]` link stem for a supersession's SOURCE-side callout: the superseding note's
/// file-stem when that note is open-on-disk + unlocked (exactly the apply-time condition), else
/// `None` (never leak a sealed meeting's title). Mirrors the apply path so a survivor replay
/// reproduces the original callout.
fn superseding_link_stem(
    state: &AppState,
    s: &crate::storage::models::SupersessionRow,
) -> Result<Option<String>, AppError> {
    let open = meeting_is_unlocked(state, &s.superseding_meeting_id)?
        && !folder_locked_on_disk(state, &s.superseding_meeting_id)?;
    if !open {
        return Ok(None);
    }
    Ok(note_file_for(state, &s.superseding_meeting_id)?.map(|(_, stem)| stem))
}

/// Read the meeting's OWN @brain THREAD TURNS for user-fact extraction (design spec D5), GATED by the
/// live session unlock snapshot: `list_assistant_interactions_visible` returns the meeting's turns
/// only when the meeting is VISIBLE (a sealed-not-unlocked meeting returns EMPTY — fail-closed). Only
/// the USER COMMAND text is included (the high-signal part — an explicit "zapamiętaj, że…"); the
/// assistant's answer is never fed back into extraction. Best-effort: any read error ⇒ empty string
/// (extraction degrades to note+notes). Content-free on error.
fn gated_meeting_thread_turns(state: &AppState, meeting_id: &str) -> String {
    let unlocked = match unlocked_snapshot(state) {
        Ok(u) => u,
        Err(_) => return String::new(),
    };
    let turns = match state
        .db
        .list_assistant_interactions_visible(meeting_id, &unlocked)
    {
        Ok(t) => t,
        Err(_) => return String::new(),
    };
    turns
        .iter()
        .map(|i| format!("User: {}", i.command.trim()))
        .collect::<Vec<_>>()
        .join("\n")
}

/// The gated cross-meeting USER MEMORY brief for injection into the non-agentic Ask / meeting-chat
/// surfaces (design spec: parity with the @brain agentic loop, which already injects it). It is
/// DERIVED data — never sealed, always REGENERATED from the currently-VISIBLE user facts under the
/// passed `unlocked` snapshot — so a sealed-not-unlocked meeting's user facts inject NOTHING. When
/// memory is disabled (config `user_memory_enabled == false`) it returns EMPTY, so the prompt is
/// byte-identical to the pre-memory prompt. Rides the EXISTING redaction + consent egress of the
/// surface it is injected into — no new egress class.
///
/// Brain v2 L2.2: `query` is the user's question when the surface has one in hand — the brief is
/// then RELEVANCE-FILTERED (BM25 top-k over the SAME visible set, `build_memory_brief`); an empty
/// query or zero hits falls back to the full-list brief (behavior-preserving).
fn gated_memory_brief_for_injection(
    state: &AppState,
    unlocked: &std::collections::HashSet<String>,
    query: &str,
) -> String {
    if !user_memory_enabled(state) {
        return String::new();
    }
    crate::user_memory::build_memory_brief(&state.db, query, unlocked)
}

/// Resolve the people + projects in a meeting note → persist them to the encrypted DB graph
/// (always) and mirror them as `[[Person]]` / `[[Project]]` vault stubs (only when a vault is
/// configured + the meeting's folder is unsealed). The graph self-assembles. The DB sink works
/// even with no vault set — hence no hard "set a vault folder" error anymore.
#[tauri::command]
pub async fn link_meeting_entities(
    app: AppHandle,
    state: State<'_, AppState>,
    meeting_id: String,
) -> Result<crate::summarize::graph::GraphPayload, AppError> {
    // BLK-2b READ-GATE: a sealed-and-not-unlocked meeting's note is blanked; refuse to extract
    // entities from it (would feed a cloud provider blank text + re-write vault stubs). Fail closed.
    if !meeting_is_unlocked(state.inner(), &meeting_id)? {
        return Err(AppError::Locked(
            "this meeting's folder is locked — unlock it to link entities".into(),
        ));
    }
    let meeting = state
        .db
        .get_meeting(&meeting_id)?
        .ok_or_else(|| AppError::InvalidArg(format!("no meeting with id {meeting_id}")))?;
    let note = state
        .db
        .get_latest_note_for_meeting(&meeting_id)?
        .ok_or_else(|| AppError::InvalidArg("this meeting has no note yet".into()))?;
    let title = meeting
        .title
        .clone()
        .unwrap_or_else(|| "Meeting".to_string());
    build_and_persist_entities(&app, &state, &meeting_id, &title, &note.markdown).await
}

/// Max co-occurring neighbors returned with an entity's detail (the neighborhood satellites).
const ENTITY_NEIGHBOR_LIMIT: i64 = 12;

/// The self-assembling graph: all VISIBLE entity nodes (with their visible mention counts) + all
/// VISIBLE co-occurrence edges. Snapshots the live session `unlocked` set (same as `list_folders`)
/// and pushes it through the visibility predicate, so sealed-and-not-unlocked meetings contribute
/// nothing — the graph can never disagree with Library/MCP about what's visible.
#[tauri::command]
pub fn get_graph(state: State<'_, AppState>) -> Result<GraphData, AppError> {
    let unlocked = unlocked_snapshot(state.inner())?;
    state.db.build_graph(&unlocked)
}

/// `/people` personal CRM: one card per VISIBLE Person entity, rolled up over the SAME gated
/// graph/facts/commitment readers as the graph + rollup views (`list_entities_visible` filtered to
/// people, `entity_mentions_visible`, `list_facts_visible`, `list_open_commitments`). Snapshots the
/// live session `unlocked` set like `get_graph`, so a person whose only mentions are in
/// sealed-and-not-session-unlocked meetings never appears and every count reflects visible sources
/// only. Read-only, no model, no new egress.
#[tauri::command]
pub fn list_people(state: State<'_, AppState>) -> Result<PeopleList, AppError> {
    let unlocked = unlocked_snapshot(state.inner())?;
    state.db.list_people(&unlocked)
}

/// Detail for one entity: the entity, its VISIBLE backlinked meetings (as `VaultSource` chips),
/// and its top co-occurring neighbors. Snapshots the live `unlocked` set like `get_graph`.
/// Errors with `InvalidArg` if the entity id is unknown.
#[tauri::command]
pub fn get_entity_detail(
    state: State<'_, AppState>,
    entity_id: String,
) -> Result<EntityDetail, AppError> {
    let unlocked = unlocked_snapshot(state.inner())?;
    state
        .db
        .build_entity_detail(&entity_id, &unlocked, ENTITY_NEIGHBOR_LIMIT)?
        .ok_or_else(|| AppError::InvalidArg(format!("no entity with id {entity_id}")))
}

/// "What links here" for a note or meeting: every VISIBLE meeting-note / standalone-note whose body
/// carries a `[[<this row's title>]]` wikilink. GATE is folded into the DB builder
/// (`Db::backlinks_for_visible`) exactly like [`get_entity_detail`] — no separate command-layer
/// pre-check. Snapshots the LIVE session unlock set, so a sealed target yields `[]` (never reveals it
/// HAS backlinks) and a sealed source never contributes. `target_kind` is `"meeting"` | `"note"`.
#[tauri::command]
pub fn get_backlinks(
    state: State<'_, AppState>,
    target_kind: String,
    target_id: String,
) -> Result<Vec<crate::storage::models::BacklinkSource>, AppError> {
    let kind = match target_kind.as_str() {
        "meeting" => crate::storage::models::SourceKind::Meeting,
        "note" => crate::storage::models::SourceKind::Note,
        other => {
            return Err(AppError::InvalidArg(format!(
                "unknown backlink target_kind {other:?} (expected \"meeting\" or \"note\")"
            )))
        }
    };
    let unlocked = unlocked_snapshot(state.inner())?;
    state.db.backlinks_for_visible(kind, &target_id, &unlocked)
}

/// Resolve a clicked `[[Title]]` wikilink to a VISIBLE note/meeting/org-item to navigate to.
/// Returns `None` when nothing matches OR the only local match is a
/// sealed-and-not-session-unlocked target (gated in `Db::resolve_wikilink`) — so a wikilink click
/// never reveals or opens locked content. The org leg (2026-07-15) is gated by membership +
/// per-instance-enabled, the same seam `list_link_candidates`/`search_org_brain_hits` use. The FE
/// routes on `kind` (`"meeting"` | `"note"` | `"org"`), or offers to create a note when `None`.
#[tauri::command]
pub fn resolve_wikilink(
    state: State<'_, AppState>,
    title: String,
) -> Result<Option<crate::storage::models::WikiTarget>, AppError> {
    let unlocked = unlocked_snapshot(state.inner())?;
    state.db.resolve_wikilink(&title, &unlocked)
}

/// Live keystroke-prefix candidates for the inline `[[` / slash-menu link-insertion autocomplete
/// (note-editor Fix 2). Distinct from [`resolve_wikilink`] (exact-title resolve on Enter/click) and
/// from `note_assistant_action`'s `find_related` (SELECTION+semantic retrieval — the wrong shape
/// for filtering on a short, growing keystroke prefix): this is a lightweight, gated title-prefix
/// scan, capped at `MAX_LINK_CANDIDATES` total rows across notes + meetings + (when joined) the
/// Shared Brain. GATED exactly like every other content read: notes/meetings go through
/// `Db::list_link_candidates_visible` (`visibility_clause` on both legs, same as `resolve_wikilink`);
/// org items go through `search_org_brain_hits`, the SAME retrieval-only, membership+enabled-gated,
/// zero-egress reader `find_related` already uses (never a provider/egress call). Reuses
/// [`crate::storage::models::NoteCitation`] — the popover renders it exactly like a `find_related`
/// citation row, and `kind == "org"` carries an org item id (never a local id), matching that
/// contract verbatim.
#[tauri::command]
pub fn list_link_candidates(
    state: State<'_, AppState>,
    prefix: String,
) -> Result<Vec<crate::storage::models::NoteCitation>, AppError> {
    const MAX_LINK_CANDIDATES: i64 = 8;
    let unlocked = unlocked_snapshot(state.inner())?;
    let mut out = state
        .db
        .list_link_candidates_visible(&prefix, MAX_LINK_CANDIDATES, &unlocked)?;
    if (out.len() as i64) < MAX_LINK_CANDIDATES {
        let config = {
            state
                .config
                .lock()
                .map_err(|_| AppError::Config("config mutex poisoned".into()))?
                .clone()
        };
        let q = prefix.trim();
        if !q.is_empty() && crate::tools::org_brain_available(&state.db, &config) {
            let remaining = (MAX_LINK_CANDIDATES - out.len() as i64).max(0) as usize;
            let org_hits = crate::tools::search_org_brain_hits(&state.db, &config, q)?;
            for hit in org_hits.into_iter().take(remaining) {
                out.push(crate::storage::models::NoteCitation {
                    kind: "org".into(),
                    id: hit.item_id,
                    title: hit.title,
                    snippet: hit.snippet,
                });
            }
        }
    }
    Ok(out)
}

/// Structured, GATED, egress-free person dossier for the `/people` detail pane. Unlike
/// [`entity_dossier`] (which CLOUD-synthesizes a markdown String via the provider and discards the
/// struct), this returns the STRUCTURED [`DossierData`](crate::summarize::dossier::DossierData) with
/// NO provider/cloud call — deterministic DB assembly, strictly MORE local-first. Gated exactly like
/// [`get_entity_detail`]/[`list_people`]: it snapshots the LIVE session unlock set and reuses
/// `build_dossier_data` VERBATIM, so a sealed-and-not-session-unlocked meeting contributes NOTHING
/// (its title, note body, commitments, and facts all stay invisible until the folder is
/// session-unlocked). `corpus` is `#[serde(skip)]`, so meeting note bodies never reach the FE.
#[tauri::command]
pub fn get_person_dossier(
    state: State<'_, AppState>,
    entity_id: String,
) -> Result<crate::summarize::dossier::DossierData, AppError> {
    get_person_dossier_inner(state.inner(), &entity_id)
}

/// Inner of [`get_person_dossier`] taking `&AppState` (unit-testable gate). `None` — an unknown id
/// OR an entity visible only through sealed-not-unlocked meetings — maps to `InvalidArg`, mirroring
/// [`get_entity_detail`] so unknown-vs-sealed-only stays indistinguishable (no existence leak).
pub(crate) fn get_person_dossier_inner(
    state: &AppState,
    entity_id: &str,
) -> Result<crate::summarize::dossier::DossierData, AppError> {
    let unlocked = unlocked_snapshot(state)?;
    crate::summarize::dossier::build_dossier_data(&state.db, entity_id, &unlocked)?
        .ok_or_else(|| AppError::InvalidArg(format!("no visible entity with id {entity_id}")))
}

/// Ask-My-Vault: answer a question across ALL past meetings' notes (grounded, with sources).
///
/// PR G (ask-unify): on the CLOUD brain backend this routes through the SAME model-driven agentic
/// loop as the in-meeting assistant — a VAULT-SCOPED gated executor (no meeting, read-only, NO
/// `propose_note`; web/calendar participate under their existing consent/availability gates) with
/// the live tool-trace on `EVENT_ASK_TOOL`. On the local/off backend, loop non-convergence, or ANY
/// loop error (incl. `Unavailable` = no cloud consent) it falls through to THE FLOOR
/// ([`ask_vault_floor`]) — exactly the pre-agentic corpus-pack + one-completion path with its
/// original error/consent semantics. `ask_thread_id` (FE camelCase `askThreadId`) is the OPTIONAL
/// thread identity stamped on every trace chip; absent ⇒ backend-generated (UUID v4).
#[tauri::command]
pub async fn ask_vault(
    app: AppHandle,
    state: State<'_, AppState>,
    question: String,
    history: Vec<ChatTurn>,
    ask_thread_id: Option<String>,
) -> Result<AskVaultResult, AppError> {
    if question.trim().is_empty() {
        return Err(AppError::InvalidArg("question is empty".into()));
    }
    let config = {
        state
            .config
            .lock()
            .map_err(|_| AppError::Config("config mutex poisoned".into()))?
            .clone()
    };
    // The same 12-message discipline as the chat panel (CHAT_CONTEXT_TURNS): bounds prompt growth +
    // cloud egress on BOTH paths. The LATEST question still drives retrieval either way.
    let history: Vec<ChatTurn> = capped_ask_history(&history).to_vec();

    // Agentic path — CLOUD-connection roles only (the same rule as the in-meeting brain:
    // local-GGUF multi-step tool-call reliability is unproven). The eligibility gate keys on the
    // ASK role's resolved target: with role keys absent, `!is_reasoner_only()` is EXACTLY the
    // legacy `brain_backend == Cloud` predicate (Cloud → provider connection, Local → "local",
    // Off → "off"). The loop is blocking (scoped-thread connectors), so it runs on a blocking
    // thread like `ask_assistant_chat`.
    if !crate::summarize::roles::resolve(crate::summarize::roles::Role::Ask, &config)
        .is_reasoner_only()
    {
        let thread_id = crate::transcribe::live::ensure_thread_id(ask_thread_id);
        let handle = app.clone();
        let q = question.clone();
        let h = history.clone();
        let attempt = tokio::task::spawn_blocking(move || {
            ask_vault_agentic_attempt(&handle, &q, &h, &thread_id)
        })
        .await
        .map_err(|e| AppError::Other(anyhow::anyhow!("ask task join failed: {e}")))?;
        if let Some(result) = attempt {
            return Ok(result);
        }
    }

    // THE FLOOR — the pre-agentic behavior, unchanged (RED-first equivalence-tested).
    // Pass the LIVE session unlock set (E9): a folder the user has session-unlocked is included
    // again, while sealed-and-NOT-unlocked content stays excluded by the same visibility predicate.
    let unlocked = unlocked_snapshot(state.inner())?;
    // Gated cross-meeting USER MEMORY brief (parity with the @brain loop): VISIBLE facts only under
    // this same unlock snapshot, empty when memory is disabled ⇒ the floor prompt is byte-identical.
    // L2.2: relevance-filtered against the question (full-list fallback on zero hits).
    let memory_brief = gated_memory_brief_for_injection(state.inner(), &unlocked, &question);
    // Brain v2 L1.4 — the Ask-only reranker: resolve from the LIVE Ask-role reasoner.
    // `active_reranker` degrades stub/cloud reasoners to the identity StubReranker (rerank is
    // strictly on-device — a cloud reasoner would turn each pointwise judgment into egress).
    let reranker = crate::rerank::active_reranker(
        state
            .reasoner
            .current_for(crate::summarize::roles::Role::Ask),
    );
    ask_vault_floor(
        &state.db,
        &config,
        &unlocked,
        &question,
        &history,
        &memory_brief,
        Some(reranker),
        &state.heavy_inference,
    )
    .await
}

/// Max agentic rounds for the Ask surface. Not live-latency-bound like the in-meeting cascade tiers
/// (`TIER1/2/3_MAX_STEPS` in `transcribe::live`, kept small so up-to-three tiers stay live-safe), so
/// the deliberately vault-wide Ask page gets a little more room to search + read — still bounded.
const ASK_MAX_STEPS: usize = 6;

/// Cap the incoming Ask history to the last [`CHAT_CONTEXT_TURNS`] turns — the same discipline as
/// the in-meeting chat panel, closing the unbounded-prompt-growth gap the pre-agentic `ask_vault`
/// had (it rendered the whole history uncapped).
fn capped_ask_history(history: &[ChatTurn]) -> &[ChatTurn] {
    let start = history.len().saturating_sub(CHAT_CONTEXT_TURNS);
    &history[start..]
}

/// Run the vault-scoped agentic attempt for [`ask_vault`]. Returns `Some(result)` ONLY when the
/// loop CONVERGED; `None` on non-convergence or ANY loop error — incl. `Unavailable` (no cloud
/// consent) — so the caller floors to the pre-agentic path with its original semantics.
fn ask_vault_agentic_attempt(
    app: &AppHandle,
    question: &str,
    history: &[ChatTurn],
    thread_id: &str,
) -> Option<AskVaultResult> {
    let state = app.state::<AppState>();
    let config = match state.config.lock() {
        Ok(c) => c.clone(),
        Err(_) => return None, // poisoned config ⇒ floor (which will surface its own error)
    };
    // Re-resolved per turn (never a startup snapshot): consent/provider/backend changes apply.
    // ASK role — under the legacy fallback this dispatches exactly like the pre-role `current()`.
    let reasoner = state
        .reasoner
        .current_for(crate::summarize::roles::Role::Ask);
    // VAULT-SCOPED executor: no live meeting, READ-ONLY, and NO note drafts (the Ask page has no
    // notes flow / Accept affordance, so `propose_note` is not advertised on this surface). The
    // AppHandle is present so web_search / calendar_lookup participate under their existing
    // consent/availability gates. Every read re-checks the LIVE unlocked set per call (C6).
    let executor = crate::tools::GatedToolExecutor {
        db: &state.db,
        unlocked: &state.unlocked_folders,
        config: &config,
        meeting_id: "",
        app: Some(app),
        allow_writes: false,
        note_drafts: false,
        // The Ask page is DELIBERATELY vault-wide (Phase 5 preserves it unchanged) — the FULL
        // per-surface catalog, NOT a cascade tier: it is not the in-meeting @brain surface the
        // current-first cascade governs.
        scope: crate::tools::AssistantScope::Full,
        // Seal-on-write handles (residual W1): read-only today (`allow_writes: false`), but the
        // executor carries the live seam so a future write surface can never silently skip it.
        seal: Some(crate::tools::SealAccess {
            master_kek: &state.master_kek,
            lifecycle: &state.lifecycle,
        }),
        proposed_note: std::sync::Mutex::new(None),
    };
    let sink = crate::transcribe::live::ToolEventSink {
        app: app.clone(),
        event: crate::events::EVENT_ASK_TOOL,
        thread_id: thread_id.to_string(),
    };
    // Gated cross-meeting USER MEMORY brief for the agentic persona (parity with the @brain loop):
    // VISIBLE facts only under the LIVE unlock snapshot, empty when memory is disabled ⇒ the persona
    // is byte-identical. Rides the loop's existing redaction + consent egress (no new class).
    let unlocked_now = state
        .unlocked_folders
        .lock()
        .map(|g| g.clone())
        .unwrap_or_default();
    let memory_brief = gated_memory_brief_for_injection(&state, &unlocked_now, question);
    // Brain v2 L3 — JIT retrieval (behind `ask_jit_retrieval`, default OFF): seed the persona with
    // a compact GATED meeting listing (id | title | date, top-30 — hybrid when semantic search is
    // on, gated FTS otherwise) + search-then-`get_meeting` instructions, instead of any pre-packed
    // content. Flag OFF passes "" ⇒ the persona is BYTE-IDENTICAL to the legacy agentic prompt.
    // Every candidate source is `visibility_clause`-gated, so a sealed-not-unlocked meeting
    // contributes no line; a listing failure degrades to the legacy prompt (never an error).
    let jit_listing = if config.ask_jit_retrieval {
        let query_vec = if config.semantic_search_enabled {
            crate::embed::active_embedder()
                .embed_query(std::slice::from_ref(&question.to_string()))
                .ok()
                .and_then(|v| v.into_iter().next())
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        crate::summarize::vault_context::build_meeting_listing_visible(
            &state.db,
            question,
            &query_vec,
            30,
            &unlocked_now,
        )
        .unwrap_or_default()
    } else {
        String::new()
    };
    // L3: the ASK preset + the `loop_transcript_compaction` flag (default ON) + the default-off
    // grammar gate (a no-op on today's cloud-only agentic reasoners).
    let opts = crate::reason::GenOptions::ask_answer()
        .with_transcript_compaction(config.loop_transcript_compaction)
        .with_grammar_constraint(config.brain_heavy_grammar_enabled);
    let org_available = crate::tools::org_brain_available(&state.db, &config);
    match ask_vault_loop(
        &*reasoner,
        &executor,
        &state.db,
        &state.unlocked_folders,
        question,
        history,
        &memory_brief,
        &jit_listing,
        org_available,
        Some(&sink as &dyn crate::agent::DeltaSink),
        opts,
    ) {
        Ok(converged) => converged,
        Err(e) => {
            // PII rule: the error only — never the question/history text.
            tracing::debug!(
                target: "ask",
                error = %e,
                "ask agentic loop unavailable/failed; flooring to corpus completion"
            );
            None
        }
    }
}

/// The testable core of the agentic Ask path: drive [`crate::agent::run_agentic_loop`] with the
/// vault-QA persona over the rendered conversation, then map a converged outcome onto the Ask DTO.
/// `Ok(None)` = non-convergence (caller floors); `Err` propagates (caller floors) — the loop
/// contract of `run_informational`, applied to the Ask surface.
///
/// `jit_listing` (Brain v2 L3) is the compact gated meeting listing for JIT retrieval — `""` (the
/// `ask_jit_retrieval`-off path) keeps the persona BYTE-IDENTICAL to the legacy agentic prompt
/// (`agentic_system_jit`'s empty-listing contract). `opts` carries the caller's per-step
/// generation bounds (the P0.3 ASK preset + the L3 compaction/grammar flags). `org_available` (A2)
/// is threaded straight to `agentic_system_jit` — the caller passes the SAME `org_brain_available`
/// predicate that gates the tool's own advertisement, so the hint and the actual tool availability
/// can never diverge.
#[allow(clippy::too_many_arguments)]
fn ask_vault_loop(
    reasoner: &dyn crate::reason::LocalReasoner,
    executor: &dyn crate::agent::ToolExecutor,
    db: &crate::storage::Db,
    unlocked: &std::sync::Mutex<std::collections::HashSet<String>>,
    question: &str,
    history: &[ChatTurn],
    memory_brief: &str,
    jit_listing: &str,
    org_available: bool,
    sink: Option<&dyn crate::agent::DeltaSink>,
    opts: crate::reason::GenOptions,
) -> Result<Option<AskVaultResult>, AppError> {
    let system =
        crate::summarize::vault_chat::agentic_system_jit(memory_brief, jit_listing, org_available);
    let user = crate::summarize::vault_chat::render_conversation(history, question);
    let Some(outcome) = crate::agent::run_agentic_loop(
        reasoner,
        &system,
        &user,
        executor,
        ASK_MAX_STEPS,
        sink,
        opts,
    )?
    else {
        return Ok(None);
    };
    // Resolve sources against the LIVE unlocked set (fail-closed on a poisoned lock: no source
    // chips rather than an ungated resolution).
    let unlocked_now = unlocked.lock().map(|g| g.clone()).unwrap_or_default();
    Ok(Some(agent_outcome_to_ask_result(
        db,
        &unlocked_now,
        outcome,
    )))
}

/// Map a converged [`crate::agent::AgentOutcome`] onto the Ask DTO. `citations` carries the loop's
/// gated citation strings verbatim (`[[Title]]` / `(web) …`); `sources` additionally resolves each
/// `[[Title]]` to its VISIBLE meeting (id + date) so the existing source chips keep working. A
/// title that doesn't resolve to a visible meeting simply contributes no source — never an error,
/// never an ungated read (`meeting_by_title_visible` applies the same visibility predicate as
/// every gated reader).
fn agent_outcome_to_ask_result(
    db: &crate::storage::Db,
    unlocked: &std::collections::HashSet<String>,
    outcome: crate::agent::AgentOutcome,
) -> AskVaultResult {
    let mut sources: Vec<crate::storage::models::VaultSource> = Vec::new();
    for cite in &outcome.citations {
        let Some(title) = cite.strip_prefix("[[").and_then(|c| c.strip_suffix("]]")) else {
            continue; // "(web) …" / "(calendar) …" attributions have no meeting to resolve.
        };
        match db.meeting_by_title_visible(title, unlocked) {
            Ok(Some(m)) if !sources.iter().any(|s| s.meeting_id == m.id) => {
                sources.push(crate::storage::models::VaultSource {
                    meeting_id: m.id,
                    title: m.title.unwrap_or_else(|| title.to_string()),
                    started_at: m.started_at,
                    origin: None,
                });
            }
            Ok(_) => {}
            Err(e) => {
                tracing::debug!(target: "ask", error = %e, "citation source resolution failed")
            }
        }
    }
    AskVaultResult {
        answer: outcome.answer,
        sources,
        citations: outcome.citations,
    }
}

/// The floor's prompt assembly, split from the provider call so the floor-equivalence test can
/// prove it byte-identical to the pre-agentic implementation without a live provider.
enum AskFloorPrompt {
    /// Nothing to search — the canned early-return result (identical to the pre-change string).
    Empty(AskVaultResult),
    /// The assembled corpus prompt, ready for ONE provider completion.
    Ready {
        system: String,
        user: String,
        sources: Vec<crate::storage::models::VaultSource>,
    },
}

/// Everything the pre-agentic `ask_vault` did BEFORE its provider call, verbatim: gated corpus
/// assembly (hybrid when semantic search is ON, FTS otherwise — Phase 2b semantics unchanged), the
/// empty-corpus early return, and the corpus prompt build. The floor-equivalence test binds this
/// to the original statement sequence.
fn build_ask_vault_floor_prompt(
    db: &crate::storage::Db,
    config: &AppConfig,
    unlocked: &std::collections::HashSet<String>,
    question: &str,
    history: &[ChatTurn],
    memory_brief: &str,
    reranker: Option<&dyn crate::rerank::Reranker>,
) -> Result<AskFloorPrompt, AppError> {
    // Phase 2b (gated): when semantic search is ON, pick candidates by HYBRID retrieval (FTS ∪
    // vector KNN, RRF-fused) — embedding the query with the active embedder — then pack with the
    // SAME budget/citation logic and the SAME visibility gate. When OFF (the default) OR the index
    // is empty, this falls back to the existing FTS-only path UNCHANGED (the hybrid query
    // degenerates to FTS when no vectors exist; the flag-off branch is byte-for-byte the prior
    // behavior).
    // Budget on the ASK-role provider's RESOLVED connection — the corpus egresses to it. With
    // role keys absent this is the legacy `provider_id` for EVERY brain_backend (the pre-role
    // floor always ignored `brain_backend`), so the packed corpus is byte-identical.
    let ask_conn =
        crate::summarize::roles::provider_target(crate::summarize::roles::Role::Ask, config)
            .connection;
    let (corpus, sources) = if config.semantic_search_enabled {
        let embedder = crate::embed::active_embedder();
        // QUERY side: use the e5 `query:` prefix (asymmetric with the `passage:` index side).
        let query_vec = embedder
            .embed_query(std::slice::from_ref(&question.to_string()))?
            .into_iter()
            .next()
            .unwrap_or_default();
        crate::summarize::vault_context::build_vault_context_hybrid_visible(
            db, question, &ask_conn, &query_vec, unlocked, reranker,
        )?
    } else {
        crate::summarize::vault_context::build_vault_context_visible(
            db, question, &ask_conn, unlocked,
        )?
    };
    if corpus.trim().is_empty() {
        return Ok(AskFloorPrompt::Empty(AskVaultResult {
            answer: "No meeting notes to search yet — record and summarize a meeting first."
                .to_string(),
            sources: Vec::new(),
            citations: Vec::new(),
        }));
    }
    let (system, user) =
        crate::summarize::vault_chat::build(&corpus, history, question, memory_brief);
    Ok(AskFloorPrompt::Ready {
        system,
        user,
        sources,
    })
}

/// THE FLOOR — the pre-agentic Ask-My-Vault implementation: gated corpus pack + ONE provider
/// completion, with the original error/consent semantics (`make_provider`'s fail-closed consent
/// gate errors exactly as before). Runs on the local/off brain backend and whenever the agentic
/// attempt did not converge or errored.
#[allow(clippy::too_many_arguments)] // cohesive gated-Ask surface: corpus/consent state + the heavy-inference permit.
async fn ask_vault_floor(
    db: &std::sync::Arc<crate::storage::Db>,
    config: &AppConfig,
    unlocked: &std::collections::HashSet<String>,
    question: &str,
    history: &[ChatTurn],
    memory_brief: &str,
    reranker: Option<Box<dyn crate::rerank::Reranker>>,
    heavy: &std::sync::Arc<tokio::sync::Semaphore>,
) -> Result<AskVaultResult, AppError> {
    // `build_ask_vault_floor_prompt` does the LOCAL/on-device work — query embedding (Candle/
    // Metal) + hybrid FTS∪vector retrieval + reranker inference — synchronously. This is exactly
    // the path privacy-first users hit (a local/reasoner-only Ask role skips the agentic branch
    // above and lands here), and it used to run INLINE on this async command's Tokio worker
    // (2026-07-13 perf audit, HIGH severity — the local path for exactly the users this app
    // targets was the one NOT already spawn_blocking'd, unlike the agentic/cloud branch above).
    // Everything captured here is owned (`Arc<Db>` clone, owned `AppConfig`/`HashSet`/`String`s,
    // a `Send + Sync` boxed reranker) so the closure is `'static` with no AppHandle re-fetch
    // needed — this function doesn't otherwise need one.
    let db_for_prompt = db.clone();
    let config_for_prompt = config.clone();
    let unlocked_for_prompt = unlocked.clone();
    let question_owned = question.to_string();
    let history_owned = history.to_vec();
    let memory_brief_owned = memory_brief.to_string();
    let prompt = tokio::task::spawn_blocking(move || {
        build_ask_vault_floor_prompt(
            &db_for_prompt,
            &config_for_prompt,
            &unlocked_for_prompt,
            &question_owned,
            &history_owned,
            &memory_brief_owned,
            reranker.as_deref(),
        )
    })
    .await
    .map_err(|e| AppError::Other(anyhow::anyhow!("ask-vault-floor task panicked: {e}")))??;
    match prompt {
        AskFloorPrompt::Empty(result) => Ok(result),
        AskFloorPrompt::Ready {
            system,
            user,
            sources,
        } => {
            // ASK role. With role keys absent this builds the legacy default provider for EVERY
            // brain_backend (the pre-role floor ignored it) — original error/consent semantics.
            let provider =
                crate::summarize::provider_for(crate::summarize::roles::Role::Ask, config, heavy)?;
            let answer = provider.complete(&system, &user).await?;
            Ok(AskVaultResult {
                answer,
                sources,
                citations: Vec::new(),
            })
        }
    }
}

#[cfg(test)]
mod ask_vault_tests {
    use super::*;
    use crate::agent::ToolExecutor;
    use crate::reason::LocalReasoner;
    use crate::storage::models::{Folder, Meeting, MeetingStatus, NoteRecord};
    use crate::storage::Db;
    use serde_json::Value;
    use std::collections::{HashSet, VecDeque};
    use std::sync::Mutex;

    const TEST_DEK: &str = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";

    fn tmp_db() -> Db {
        let p = crate::storage::db::unique_temp_path("murmur-askvault", "sqlite");
        Db::open_with_key(&p, TEST_DEK).unwrap()
    }

    fn block_on<F: std::future::Future>(f: F) -> F::Output {
        tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap()
            .block_on(f)
    }

    fn seed_note(db: &Db, id: &str, title: &str, markdown: &str, folder: Option<&str>) {
        db.insert_meeting(&Meeting {
            id: id.into(),
            started_at: "2026-06-26T09:00:00Z".into(),
            ended_at: None,
            title: Some(title.into()),
            duration_s: 60,
            audio_path: None,
            status: MeetingStatus::Summarized,
            folder_id: None,
        })
        .unwrap();
        db.upsert_note(&NoteRecord {
            meeting_id: id.into(),
            provider_id: "claude_code".into(),
            markdown: markdown.into(),
            created_at: "2026-06-26T09:05:00Z".into(),
            exported_path: None,
            model_requested: None,
            model_served: None,
            gateway_host: None,
        })
        .unwrap();
        db.set_note_folder(id, folder).unwrap();
    }

    /// A LOCKED folder + a blanked-note meeting inside it — the sealed-and-not-unlocked at-rest
    /// shape (title still indexed; the visibility gate is what must hide it).
    fn seed_sealed(db: &Db, meeting_id: &str, folder_id: &str, title: &str) {
        db.insert_folder(&Folder {
            id: folder_id.into(),
            name: "Secret".into(),
            path: "Secret".into(),
            parent_id: None,
            locked: true,
            created_at: "2026-06-26T00:00:00Z".into(),
        })
        .unwrap();
        seed_note(db, meeting_id, title, "", Some(folder_id));
    }

    /// A reasoner whose `structured()` returns canned JSON in sequence (a test double — the
    /// production loop drives the real ReasonerCell dispatch). Exhaustion yields an empty answer,
    /// which the loop treats as non-convergence.
    struct ScriptReasoner {
        script: Mutex<VecDeque<crate::error::Result<Value>>>,
    }
    impl ScriptReasoner {
        fn ok(steps: Vec<Value>) -> Self {
            Self {
                script: Mutex::new(steps.into_iter().map(Ok).collect()),
            }
        }
    }
    impl LocalReasoner for ScriptReasoner {
        fn id(&self) -> &str {
            "script"
        }
        fn reason(&self, _s: &str, _u: &str) -> crate::error::Result<String> {
            Ok("unused".into())
        }
        fn structured(&self, _s: &str, _u: &str, _schema: &Value) -> crate::error::Result<Value> {
            self.script
                .lock()
                .unwrap()
                .pop_front()
                .unwrap_or_else(|| Ok(serde_json::json!({ "answer": "" })))
        }
    }

    /// The VAULT-SCOPED executor exactly as `ask_vault_agentic_attempt` builds it (no meeting,
    /// read-only, NO note drafts), minus the AppHandle (headless: connectors unavailable).
    fn ask_executor<'a>(
        db: &'a Db,
        unlocked: &'a Mutex<HashSet<String>>,
        cfg: &'a AppConfig,
    ) -> crate::tools::GatedToolExecutor<'a> {
        crate::tools::GatedToolExecutor {
            db,
            unlocked,
            config: cfg,
            meeting_id: "",
            app: None,
            allow_writes: false,
            note_drafts: false,
            scope: crate::tools::AssistantScope::Full,
            seal: None,
            proposed_note: Mutex::new(None),
        }
    }

    /// Brain v2 L3 — the flag-ON JIT wiring, bound headless (adversarial finding 2026-07-10: only
    /// the flag-OFF byte-identity was tested): the exact glue `ask_vault_agentic_attempt` runs
    /// when `ask_jit_retrieval` is ON — `build_meeting_listing_visible` (gated; the FTS/recency
    /// path with semantic search off) fed through `ask_vault_loop` → `agentic_system_jit` — must
    /// inject the "MEETING LISTING" section WITH the visible meeting's `id | title | date` line
    /// into the system prompt the model actually sees. The AppState-driven flag read in
    /// `ask_vault_agentic_attempt` itself stays code-read-verified (it needs a running app).
    #[test]
    fn ask_jit_flag_on_injects_the_gated_listing_into_the_system_prompt() {
        /// Records every SYSTEM prompt handed to the model, then answers immediately.
        struct SystemRecordingReasoner {
            systems: Mutex<Vec<String>>,
        }
        impl LocalReasoner for SystemRecordingReasoner {
            fn id(&self) -> &str {
                "system-recording"
            }
            fn reason(&self, _s: &str, _u: &str) -> crate::error::Result<String> {
                Ok(String::new())
            }
            fn structured(
                &self,
                s: &str,
                _u: &str,
                _schema: &Value,
            ) -> crate::error::Result<Value> {
                self.systems.lock().unwrap().push(s.to_string());
                Ok(serde_json::json!({ "answer": "done" }))
            }
        }

        let db = tmp_db();
        seed_note(
            &db,
            "m1",
            "Atlas Kickoff",
            "We decided to ship atlas on Friday.",
            None,
        );
        let cfg = AppConfig::default();
        let unlocked = Mutex::new(HashSet::new());
        let exec = ask_executor(&db, &unlocked, &cfg);

        // The flag-ON branch of `ask_vault_agentic_attempt`, headless shape: semantic search off
        // ⇒ empty query vector ⇒ the gated FTS/recency listing.
        let listing = crate::summarize::vault_context::build_meeting_listing_visible(
            &db,
            "atlas",
            &[],
            30,
            &HashSet::new(),
        )
        .unwrap();
        assert!(
            listing.contains("Atlas Kickoff"),
            "seed self-check: the visible meeting must be listed: {listing}"
        );

        let r = SystemRecordingReasoner {
            systems: Mutex::new(Vec::new()),
        };
        let out = ask_vault_loop(
            &r,
            &exec,
            &db,
            &unlocked,
            "atlas?",
            &[],
            "",
            &listing,
            false,
            None,
            crate::reason::GenOptions::ask_answer(),
        )
        .unwrap()
        .expect("scripted brain converged");
        assert_eq!(out.answer, "done");
        let systems = r.systems.lock().unwrap();
        let sys = systems.first().expect("at least one model turn");
        assert!(
            sys.contains("MEETING LISTING"),
            "flag-ON must inject the JIT listing section into the system prompt"
        );
        assert!(
            sys.contains("Atlas Kickoff") && sys.contains("m1"),
            "the visible meeting's `id | title | date` line must reach the model"
        );
    }

    /// RED-first floor equivalence (the binding test of "the floor is today's behavior"): the
    /// extracted floor prompt must be BYTE-IDENTICAL to the pre-change statement sequence —
    /// `build_vault_context_visible` → `vault_chat::build` — for the same inputs, and the
    /// empty-corpus early return must keep the exact canned string. RED-proven: perturbing the
    /// floor (e.g. swapping the corpus builder for the fail-closed shim, or reordering sections)
    /// fails the byte equality here.
    #[test]
    fn ask_floor_prompt_matches_pre_change_implementation() {
        let db = tmp_db();
        seed_note(
            &db,
            "m1",
            "Atlas Kickoff",
            "We decided to ship atlas on Friday.",
            None,
        );
        seed_note(&db, "m2", "Weekly Sync", "Anna owns QA for atlas.", None);
        // Tier 1 flipped the semantic default ON; PIN it false so this test keeps EXPLICITLY exercising
        // the FTS-floor branch (its stated purpose) rather than the hybrid branch — which, on an empty
        // vec_chunks, happens to degenerate to the same bytes. Defensive/self-documenting, not a strict
        // regression guard (the hybrid path is byte-identical here even without the pin).
        let cfg = AppConfig {
            semantic_search_enabled: false,
            ..AppConfig::default()
        };
        let unlocked = HashSet::new();
        let history = vec![
            ChatTurn {
                role: "user".into(),
                content: "earlier question".into(),
            },
            ChatTurn {
                role: "assistant".into(),
                content: "earlier answer".into(),
            },
        ];
        let q = "what did we decide about atlas?";

        // The PRE-CHANGE implementation, replicated statement-for-statement.
        let (corpus, want_sources) = crate::summarize::vault_context::build_vault_context_visible(
            &db,
            q,
            &cfg.provider_id,
            &unlocked,
        )
        .unwrap();
        assert!(
            !corpus.trim().is_empty(),
            "fixture must produce a non-empty corpus"
        );
        // Empty memory brief ⇒ the floor prompt must stay BYTE-IDENTICAL to the pre-memory build.
        let (want_system, want_user) =
            crate::summarize::vault_chat::build(&corpus, &history, q, "");

        match build_ask_vault_floor_prompt(&db, &cfg, &unlocked, q, &history, "", None).unwrap() {
            AskFloorPrompt::Ready {
                system,
                user,
                sources,
            } => {
                assert_eq!(
                    system, want_system,
                    "floor system prompt diverged from pre-change"
                );
                assert_eq!(
                    user, want_user,
                    "floor user prompt diverged from pre-change"
                );
                assert_eq!(
                    sources
                        .iter()
                        .map(|s| s.meeting_id.as_str())
                        .collect::<Vec<_>>(),
                    want_sources
                        .iter()
                        .map(|s| s.meeting_id.as_str())
                        .collect::<Vec<_>>(),
                    "floor sources diverged from pre-change"
                );
            }
            AskFloorPrompt::Empty(_) => panic!("a non-empty corpus must yield Ready"),
        }

        // The empty-vault early return keeps the EXACT pre-change canned answer.
        let empty = tmp_db();
        match build_ask_vault_floor_prompt(&empty, &cfg, &unlocked, q, &[], "", None).unwrap() {
            AskFloorPrompt::Empty(r) => {
                assert_eq!(
                    r.answer,
                    "No meeting notes to search yet — record and summarize a meeting first."
                );
                assert!(r.sources.is_empty() && r.citations.is_empty());
            }
            AskFloorPrompt::Ready { .. } => panic!("an empty vault must yield the canned Empty"),
        }
    }

    /// The floor's ERROR/CONSENT semantics are untouched: an unconsented cloud provider is refused
    /// by `make_provider`'s fail-closed gate with `AppError::Unavailable` — exactly the pre-change
    /// behavior the FE consent flow keys on.
    #[test]
    fn ask_floor_preserves_no_consent_error_semantics() {
        let db = tmp_db();
        seed_note(
            &db,
            "m1",
            "Atlas Kickoff",
            "We decided to ship atlas on Friday.",
            None,
        );
        let cfg = AppConfig {
            provider_id: "anthropic".into(),
            ..AppConfig::default()
        };
        assert!(
            !cfg.cloud_egress_consented,
            "fresh config defaults to consent OFF"
        );
        let db = std::sync::Arc::new(db);
        let res = block_on(ask_vault_floor(
            &db,
            &cfg,
            &HashSet::new(),
            "atlas?",
            &[],
            "",
            None,
            &std::sync::Arc::new(tokio::sync::Semaphore::new(1)),
        ));
        assert!(
            matches!(res, Err(AppError::Unavailable(_))),
            "no-consent floor must keep the Unavailable refusal: {res:?}"
        );
    }

    /// The Cloud loop path: a scripted brain calls a GATED tool, answers, and the tool-derived
    /// `[[Title]]` citations flow into the DTO — verbatim in `citations` AND resolved (gated) into
    /// the structured `sources` chips.
    #[test]
    fn ask_loop_tool_citations_flow_into_dto() {
        let db = tmp_db();
        seed_note(
            &db,
            "m1",
            "Atlas Kickoff",
            "## Action items\n- [ ] Anna — ship the deck 2026-07-10\n",
            None,
        );
        let cfg = AppConfig::default();
        let unlocked = Mutex::new(HashSet::new());
        let exec = ask_executor(&db, &unlocked, &cfg);
        let brain = ScriptReasoner::ok(vec![
            serde_json::json!({ "tool": "get_open_commitments", "args": {} }),
            serde_json::json!({ "answer": "Anna ships the deck by 2026-07-10 [[Atlas Kickoff]]." }),
        ]);
        let out = ask_vault_loop(
            &brain,
            &exec,
            &db,
            &unlocked,
            "who owns the deck?",
            &[],
            "",
            "",
            false,
            None,
            crate::reason::GenOptions::ask_answer(),
        )
        .unwrap()
        .expect("scripted brain converged");
        assert_eq!(
            out.answer,
            "Anna ships the deck by 2026-07-10 [[Atlas Kickoff]]."
        );
        assert!(
            out.citations.contains(&"[[Atlas Kickoff]]".to_string()),
            "tool-derived citation must reach the DTO verbatim: {:?}",
            out.citations
        );
        assert_eq!(
            out.sources.len(),
            1,
            "the citation resolves to ONE source chip"
        );
        assert_eq!(out.sources[0].meeting_id, "m1");
        assert_eq!(out.sources[0].title, "Atlas Kickoff");
        assert_eq!(out.sources[0].started_at, "2026-06-26T09:00:00Z");
    }

    /// The loop contract at this surface: non-convergence → `Ok(None)` (the command floors); a
    /// reasoner error — the no-consent `Unavailable` — PROPAGATES (the command's attempt wrapper
    /// converts it to a floor, whose semantics `ask_floor_preserves_no_consent_error_semantics`
    /// pins).
    #[test]
    fn ask_loop_non_convergence_floors_and_errors_propagate() {
        let db = tmp_db();
        let cfg = AppConfig::default();
        let unlocked = Mutex::new(HashSet::new());
        let exec = ask_executor(&db, &unlocked, &cfg);

        // Script exhaustion yields an empty answer → the loop bails without converging.
        let stuck = ScriptReasoner::ok(vec![
            serde_json::json!({ "tool": "search_meetings", "args": { "query": "a" } }),
        ]);
        let out = ask_vault_loop(
            &stuck,
            &exec,
            &db,
            &unlocked,
            "q",
            &[],
            "",
            "",
            false,
            None,
            crate::reason::GenOptions::ask_answer(),
        )
        .unwrap();
        assert!(
            out.is_none(),
            "non-convergence must return Ok(None) for the command to floor"
        );

        struct Refuses;
        impl LocalReasoner for Refuses {
            fn id(&self) -> &str {
                "refuses"
            }
            fn reason(&self, _s: &str, _u: &str) -> crate::error::Result<String> {
                Ok("unused".into())
            }
            fn structured(
                &self,
                _s: &str,
                _u: &str,
                _schema: &Value,
            ) -> crate::error::Result<Value> {
                Err(AppError::Unavailable("no consent".into()))
            }
        }
        let res = ask_vault_loop(
            &Refuses,
            &exec,
            &db,
            &unlocked,
            "q",
            &[],
            "",
            "",
            false,
            None,
            crate::reason::GenOptions::ask_answer(),
        );
        assert!(
            matches!(res, Err(AppError::Unavailable(_))),
            "a loop error must propagate so the attempt wrapper can floor: {res:?}"
        );
    }

    /// The 12-message history discipline (CHAT_CONTEXT_TURNS) now applies to Ask: a 13th message
    /// is dropped from both the capped slice and the rendered conversation. RED vs the pre-change
    /// code, which rendered the history uncapped.
    #[test]
    fn ask_history_cap_enforced() {
        let msgs: Vec<ChatTurn> = (0..13)
            .map(|i| ChatTurn {
                role: "user".into(),
                content: format!("turn-{i}-text"),
            })
            .collect();
        let capped = capped_ask_history(&msgs);
        assert_eq!(capped.len(), CHAT_CONTEXT_TURNS);
        assert_eq!(
            capped[0].content, "turn-1-text",
            "the oldest message beyond the cap is dropped"
        );
        let rendered = crate::summarize::vault_chat::render_conversation(capped, "final question");
        assert!(
            !rendered.contains("turn-0-text"),
            "turn beyond the cap must not render"
        );
        assert!(
            rendered.contains("turn-12-text"),
            "the newest capped turn renders"
        );
        assert!(
            rendered.trim_end().ends_with("Assistant:"),
            "render keeps the completion cue"
        );

        // A short history passes through untouched.
        assert_eq!(capped_ask_history(&msgs[..3]).len(), 3);
    }

    /// SURFACE SPLIT: the vault executor must NOT advertise `propose_note` (the Ask page has no
    /// notes flow / Accept affordance) and must REFUSE to run it (the allowlist fails closed);
    /// the in-meeting executor (note_drafts: true) still advertises it. RED-able: drop the
    /// `"propose_note" => self.note_drafts` filter arm and the first assertion fails.
    #[test]
    fn propose_note_hidden_on_ask_surface_but_kept_in_meeting() {
        let db = tmp_db();
        let cfg = AppConfig::default();
        let unlocked = Mutex::new(HashSet::new());

        let vault = ask_executor(&db, &unlocked, &cfg);
        let names_specs = vault.specs();
        let names: Vec<&str> = names_specs.iter().map(|s| s.name.as_str()).collect();
        assert!(
            !names.contains(&"propose_note"),
            "the Ask surface must not advertise propose_note: {names:?}"
        );
        let res = vault.run("propose_note", &serde_json::json!({ "content": "draft" }));
        assert!(
            matches!(res, Err(AppError::InvalidArg(_))),
            "an un-advertised propose_note must be refused by the allowlist: {res:?}"
        );

        let in_meeting = crate::tools::GatedToolExecutor {
            db: &db,
            unlocked: &unlocked,
            config: &cfg,
            meeting_id: "live1",
            app: None,
            allow_writes: false,
            note_drafts: true,
            scope: crate::tools::AssistantScope::Full,
            seal: None,
            proposed_note: Mutex::new(None),
        };
        assert!(
            in_meeting.specs().iter().any(|s| s.name == "propose_note"),
            "the in-meeting surface keeps propose_note advertised"
        );
    }

    /// LOCK INVARIANT at the Ask surface: a scripted brain that tries to exfiltrate a
    /// sealed-not-unlocked meeting through the vault executor surfaces NOTHING sealed — not in the
    /// direct tool reads, not in the DTO's citations, not in the resolved `sources` (the
    /// citation→source resolver applies the same visibility predicate and only resolves once the
    /// folder is session-unlocked).
    #[test]
    fn ask_loop_never_surfaces_sealed_content() {
        let db = tmp_db();
        seed_note(
            &db,
            "open1",
            "Atlas Kickoff",
            "We decided to ship atlas on Friday.",
            None,
        );
        seed_sealed(&db, "sealed1", "fsec", "Atlas Secret Terms");

        // Seed self-check: the fixture must be sealed-not-unlocked BEFORE we prove the gate.
        let nothing = HashSet::new();
        assert!(db.meeting_is_visible("open1", &nothing).unwrap());
        assert!(
            !db.meeting_is_visible("sealed1", &nothing).unwrap(),
            "seed fixture: sealed1 must be gated"
        );

        let cfg = AppConfig::default();
        let unlocked = Mutex::new(HashSet::new());
        let exec = ask_executor(&db, &unlocked, &cfg);

        // Direct gate proof on THIS surface's executor shape.
        let got = exec
            .run(
                "get_meeting",
                &serde_json::json!({ "meetingId": "sealed1" }),
            )
            .unwrap();
        assert!(
            got.starts_with("No data"),
            "sealed fetch must be gated: {got}"
        );

        // The full loop, driven by an exfiltrating script.
        let brain = ScriptReasoner::ok(vec![
            serde_json::json!({ "tool": "get_meeting", "args": { "meetingId": "sealed1" } }),
            serde_json::json!({ "tool": "search_meetings", "args": { "query": "Atlas Secret Terms" } }),
            serde_json::json!({ "answer": "Here is what I found." }),
        ]);
        let out = ask_vault_loop(
            &brain,
            &exec,
            &db,
            &unlocked,
            "the secret terms?",
            &[],
            "",
            "",
            false,
            None,
            crate::reason::GenOptions::ask_answer(),
        )
        .unwrap()
        .expect("converged");
        assert!(
            out.citations.iter().all(|c| !c.contains("Secret")),
            "sealed title must never be cited: {:?}",
            out.citations
        );
        assert!(
            out.sources.iter().all(|s| s.meeting_id != "sealed1"),
            "sealed meeting must never resolve into sources: {:?}",
            out.sources
        );

        // The resolver itself is gated: the sealed title resolves ONLY once session-unlocked.
        assert!(
            db.meeting_by_title_visible("Atlas Secret Terms", &nothing)
                .unwrap()
                .is_none(),
            "sealed-not-unlocked title must not resolve"
        );
        let mut open = HashSet::new();
        open.insert("fsec".to_string());
        assert_eq!(
            db.meeting_by_title_visible("Atlas Secret Terms", &open)
                .unwrap()
                .expect("session-unlocked title resolves")
                .id,
            "sealed1"
        );
    }

    /// The Ask trace stream is its OWN event — record-screen stores must never see Ask chips.
    #[test]
    fn ask_tool_event_is_distinct() {
        assert_ne!(
            crate::events::EVENT_ASK_TOOL,
            crate::events::EVENT_ASSISTANT_TOOL
        );
        assert_ne!(
            crate::events::EVENT_ASK_TOOL,
            crate::events::EVENT_CHAT_TOOL
        );
    }
}

/// Entity DOSSIER (brain2 Phase 5b): synthesize the "state of [[entity]]" across all meetings —
/// Overview · 🕑 Timeline of mentions · ⏳ Open commitments · 🧭 Last said / next step, every claim
/// citing its [[Title]]. `entity` is an entity id (from `get_graph`) OR a name. The dossier data is
/// assembled through the SAME visibility gate as Ask-My-Vault (sealed-not-unlocked meetings
/// contribute nothing), then synthesized by the configured provider — so this is a CLOUD-egress
/// path that goes through the redaction firewall + consent gate (E6/E7/E10) exactly like `ask_vault`.
///
/// B2 (Shared Brain, READ-ONLY): when the caller has joined an org, ALSO searches the org partition
/// for this entity and folds `[org · author]`-labelled hits into the SYNTHESIS PROMPT ONLY as
/// additional citable context — an entity with ZERO local facts/mentions can still resolve here
/// purely from org content. This NEVER calls `build_and_persist_entities` and NEVER writes anything
/// derived from org content into `entities`/`entity_mentions`/`facts` — those tables are untouched
/// by this path. `has_org_context` on the response is the honest signal that org-sourced content
/// contributed, so the caller never silently blends a colleague's claims with the user's own
/// verified facts.
#[tauri::command]
pub async fn entity_dossier(
    state: State<'_, AppState>,
    entity: String,
) -> Result<EntityDossierResult, AppError> {
    let config = {
        state
            .config
            .lock()
            .map_err(|_| AppError::Config("config mutex poisoned".into()))?
            .clone()
    };
    // Pass the LIVE session unlock set (E9): a folder the user has session-unlocked is included
    // again; sealed-and-NOT-unlocked content stays excluded by the same visibility predicate.
    let unlocked = unlocked_snapshot(state.inner())?;
    let notes_conn =
        crate::summarize::roles::provider_target(crate::summarize::roles::Role::Notes, &config)
            .connection;
    let (system, user, has_org_context) =
        build_entity_dossier_prompt(&state.db, &entity, &unlocked, &config, &notes_conn)?;
    // Build the provider (firewall + consent gate) BEFORE synthesizing — the factory refuses a
    // cloud provider until the user has consented to egress. NOTES role (the dossier is a
    // written synthesis); the corpus budget keys on the same resolved connection.
    let provider = crate::summarize::provider_for(crate::summarize::roles::Role::Notes, &config, &state.heavy_inference)?;
    let markdown = provider.complete(&system, &user).await?;
    Ok(EntityDossierResult {
        markdown,
        has_org_context,
    })
}

/// The testable, SYNCHRONOUS core of [`entity_dossier`]: resolve the entity + gated local dossier
/// data, ALSO run the READ-ONLY org leg (B2), and assemble the (system, user, has_org_context)
/// synthesis-prompt triple — everything short of the actual `provider.complete` cloud call, so this
/// can be tested without a real provider/network.
///
/// B2 (Shared Brain, READ-ONLY): when the caller has joined an org (`org_brain_available`), ALSO
/// searches the org partition ONCE for this entity and folds `[org · author]`-labelled hits into
/// the synthesis prompt ONLY — an entity with ZERO local facts/mentions can still resolve here
/// purely from org content (`data` may be `None` while `org_context` is `Some`). This function NEVER
/// calls `build_and_persist_entities` and NEVER writes to `entities`/`entity_mentions`/`facts` — it
/// only reads. `has_org_context` is `true` iff org-sourced lines were folded in, so the caller can
/// honestly signal that the dossier drew on colleague content.
fn build_entity_dossier_prompt(
    db: &crate::storage::Db,
    entity: &str,
    unlocked: &std::collections::HashSet<String>,
    config: &AppConfig,
    notes_conn: &str,
) -> Result<(String, String, bool), AppError> {
    if entity.trim().is_empty() {
        return Err(AppError::InvalidArg("entity is empty".into()));
    }
    // B2: resolve the ORG leg once, up front — an entity that is ORG-ONLY (no local entity row at
    // all) must still be resolvable, so the local-entity lookup below is allowed to miss as long as
    // org content is present. Gated on the SAME `org_brain_available` predicate as every other org
    // leg (A1/A2); one call, no per-query looping. READ-ONLY: `search_org_brain` never writes.
    let org_query = entity.trim().to_string();
    let org_context = if crate::tools::org_brain_available(db, config) {
        match crate::tools::search_org_brain(db, config, &org_query) {
            Ok(text) => {
                let text = text.trim();
                // `search_org_brain` degrades to a "No org-brain results …" sentinel (never an Err)
                // when there is nothing to find — that carries no `- [org` line, so it is dropped
                // here exactly like every other "nothing found" sentinel this codebase filters
                // (`voice_action::is_empty_tool_result`). A real hit's text is passed THROUGH
                // WHOLE (never re-split by line) — a snippet can legitimately wrap onto a second
                // line that doesn't itself start with "- [org", and truncating there would silently
                // drop cited content from the synthesis prompt.
                if text.is_empty() || !text.contains("- [org") {
                    None
                } else {
                    Some(text.to_string())
                }
            }
            Err(e) => {
                tracing::debug!(
                    target: "dossier",
                    error = %e,
                    "entity dossier org-brain search failed; continuing without org context"
                );
                None
            }
        }
    } else {
        None
    };

    let entity_id = crate::summarize::dossier::resolve_entity_id(db, entity, unlocked)?;
    let data = match entity_id {
        Some(id) => crate::summarize::dossier::build_dossier_data(db, &id, unlocked)?,
        None => None,
    };
    // Neither a local entity NOR any org context ⇒ genuinely unknown — the pre-org error semantics.
    if data.is_none() && org_context.is_none() {
        return Err(AppError::InvalidArg(format!(
            "no visible entity matching \"{entity}\""
        )));
    }
    let mut system = crate::summarize::dossier::dossier_system_prompt(&config.note_language);
    let mut user = match &data {
        Some(d) => crate::summarize::dossier::render_dossier_user(d, notes_conn),
        // Org-only entity: no local dossier data at all — hand the model just the entity name so it
        // has a subject to synthesize the org section against.
        None => format!(
            "ENTITY: {}\n(no local meetings/facts found for this entity)\n",
            entity.trim()
        ),
    };
    let has_org_context = if let Some(org_lines) = &org_context {
        system.push_str(
            " Additional context may include lines starting \"- [org ·\" — these are colleague-\
             shared facts from your organization's Shared Brain, NOT the user's own verified data. \
             Attribute any claim drawn from them by their \"[org · author]\" provenance, clearly \
             distinguished from the user's own meetings/facts.",
        );
        user.push_str(&format!(
            "\n\nADDITIONAL CONTEXT FROM YOUR ORGANIZATION'S SHARED BRAIN (colleague-shared, \
             attribute by provenance):\n{org_lines}\n"
        ));
        true
    } else {
        false
    };
    Ok((system, user, has_org_context))
}

#[cfg(test)]
mod entity_dossier_tests {
    use super::*;
    use crate::storage::models::{Meeting, MeetingStatus, NoteRecord};
    use crate::storage::Db;
    use std::collections::HashSet;

    const TEST_DEK: &str = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";

    fn tmp_db() -> Db {
        let p = crate::storage::db::unique_temp_path("murmur-dossier", "sqlite");
        Db::open_with_key(&p, TEST_DEK).unwrap()
    }

    fn seed_note(db: &Db, id: &str, title: &str, markdown: &str) {
        db.insert_meeting(&Meeting {
            id: id.into(),
            started_at: "2026-06-26T09:00:00Z".into(),
            ended_at: None,
            title: Some(title.into()),
            duration_s: 60,
            audio_path: None,
            status: MeetingStatus::Summarized,
            folder_id: None,
        })
        .unwrap();
        db.upsert_note(&NoteRecord {
            meeting_id: id.into(),
            provider_id: "claude_code".into(),
            markdown: markdown.into(),
            created_at: "2026-06-26T09:05:00Z".into(),
            exported_path: None,
            model_requested: None,
            model_served: None,
            gateway_host: None,
        })
        .unwrap();
    }

    /// Join org-1 for this session (mirrors `tools::tests::seed_org`).
    fn seed_org(db: &Db) {
        db.upsert_org_state(&crate::storage::OrgState {
            org_id: "org-1".to_string(),
            name: "Acme".to_string(),
            role: "member".to_string(),
            joined_at: "2026-07-10T00:00:00Z".to_string(),
            consented: true,
            last_seq: 0,
            generation: 1,
            context_enabled: true,
        })
        .unwrap();
    }

    /// Ingest one org-brain item into the local replica (mirrors `tools::tests::ingest_org`).
    fn ingest_org(db: &Db, item_id: &str, author: &str, title: &str, body: &str, sha: &[u8]) {
        db.upsert_org_item(
            item_id,
            "org-1",
            1,
            author,
            title,
            body,
            "2026-07-10T09:00:00Z",
            1,
            1,
            sha,
            None,
            None,
            Some(&crate::embed::StubEmbedder),
        )
        .unwrap();
    }

    fn empty_unlocked() -> HashSet<String> {
        HashSet::new()
    }

    /// RED-before-GREEN (B2, the load-bearing leak/write-safety test): an entity that exists ONLY in
    /// the org brain — ZERO local `entities`/`entity_mentions`/`facts` rows for it at all — must now
    /// resolve via the dossier prompt builder with `[org · author]`-cited content, AND the local
    /// `entities`/`entity_mentions` tables (proxied via `list_entities_visible` — row count + summed
    /// visible mention count) must be BYTE-IDENTICAL (same COUNT) before and after the call, proving
    /// the org leg is READ-ONLY and never calls `build_and_persist_entities` / writes derived rows.
    /// Pre-fix, an org-only entity had NO local row at all and `resolve_entity_id` returned `None`
    /// unconditionally ⇒ `InvalidArg("no visible entity matching …")` — RED.
    #[test]
    fn org_only_entity_resolves_via_dossier_and_writes_nothing_to_local_tables() {
        let db = tmp_db();
        seed_org(&db);
        ingest_org(
            &db,
            "it-1",
            "anna",
            "Anna's roadmap",
            "Project Apollo: the apollo migration ships friday, owned by anna",
            &[3u8; 32],
        );
        let unlocked = empty_unlocked();
        let cfg = AppConfig {
            semantic_search_enabled: false,
            ..AppConfig::default()
        };

        // BASELINE row counts — a fresh DB with an org item but NO local entities/mentions at all.
        let entities_before = db.list_entities_visible(&unlocked).unwrap();
        let count_before = entities_before.len();
        let mentions_before: i64 = entities_before.iter().map(|e| e.mention_count).sum();

        // "Project Apollo" is ORG-ONLY — no local meeting/entity ever mentions it.
        let (system, user, has_org_context) =
            build_entity_dossier_prompt(&db, "Project Apollo", &unlocked, &cfg, "claude_code")
                .expect("an org-only entity must now resolve (RED on the pre-fix hard miss)");

        assert!(has_org_context, "has_org_context must be true when org content contributed");
        assert!(
            user.contains("[org · anna]") && user.contains("apollo migration"),
            "the org-cited content must reach the synthesis USER prompt: {user}"
        );
        assert!(
            system.contains("[org ·"),
            "the synthesis SYSTEM prompt must instruct org-provenance attribution: {system}"
        );

        // THE LOAD-BEARING ASSERTION: local entities/entity_mentions rows are UNCHANGED — the org
        // leg never persisted anything derived from org content.
        let entities_after = db.list_entities_visible(&unlocked).unwrap();
        let count_after = entities_after.len();
        let mentions_after: i64 = entities_after.iter().map(|e| e.mention_count).sum();
        assert_eq!(
            count_before, count_after,
            "entities row count must be UNCHANGED by a read-only org-context dossier call"
        );
        assert_eq!(
            mentions_before, mentions_after,
            "entity_mentions row count (proxied via summed visible mention_count) must be UNCHANGED"
        );
        assert!(
            count_after == 0 && mentions_after == 0,
            "an org-only entity must create NO local entity/mention row at all: entities={count_after} mentions={mentions_after}"
        );
    }

    /// Companion: seed a REAL local entity (with its own mention + zero facts) so the baseline
    /// tables are non-empty, then run a dossier call for a DIFFERENT org-only entity — the
    /// pre-existing local entity's own facts (`list_facts_visible`) must stay untouched (still
    /// empty), proving the org leg doesn't bleed into or mutate UNRELATED existing rows either.
    #[test]
    fn org_context_dossier_call_never_touches_an_unrelated_local_entitys_facts() {
        let db = tmp_db();
        seed_org(&db);
        ingest_org(
            &db,
            "it-2",
            "bob",
            "Bob's plan",
            "Project Zephyr: the zephyr rollout ships monday",
            &[7u8; 32],
        );
        seed_note(&db, "m1", "Atlas Kickoff", "We discussed Atlas migration and pricing.");
        let entity_id = db
            .upsert_entity("Atlas", crate::storage::models::EntityKind::Project)
            .unwrap();
        db.add_mention(&entity_id, "m1").unwrap();

        let unlocked = empty_unlocked();
        let cfg = AppConfig {
            semantic_search_enabled: false,
            ..AppConfig::default()
        };
        let facts_before = db.list_facts_visible(&entity_id, &unlocked).unwrap().len();
        assert_eq!(facts_before, 0, "seed self-check: no facts yet for the local entity");

        // Dossier call for a DIFFERENT, org-only entity.
        let (_, _, has_org_context) =
            build_entity_dossier_prompt(&db, "Project Zephyr", &unlocked, &cfg, "claude_code")
                .expect("org-only entity must resolve");
        assert!(has_org_context);

        // The pre-existing LOCAL entity's facts are untouched by the unrelated org-context call.
        let facts_after = db.list_facts_visible(&entity_id, &unlocked).unwrap().len();
        assert_eq!(
            facts_after, 0,
            "an unrelated local entity's facts must stay UNCHANGED by an org-context dossier call"
        );
        // And the local entity itself still resolves exactly as before (not clobbered/duplicated).
        let entities = db.list_entities_visible(&unlocked).unwrap();
        assert_eq!(
            entities.iter().filter(|e| e.name == "Atlas").count(),
            1,
            "the pre-existing local entity must not be duplicated or removed"
        );
    }

    /// A local-only entity (no org membership at all) keeps the EXACT pre-org behavior:
    /// `has_org_context` is false and no org text reaches the prompt.
    #[test]
    fn local_only_entity_has_org_context_false_and_no_org_text_when_not_a_member() {
        let db = tmp_db();
        seed_note(&db, "m1", "Atlas Kickoff", "We discussed Atlas migration and pricing.");
        let entity_id = db
            .upsert_entity("Atlas", crate::storage::models::EntityKind::Project)
            .unwrap();
        db.add_mention(&entity_id, "m1").unwrap();

        let unlocked = empty_unlocked();
        let cfg = AppConfig {
            semantic_search_enabled: false,
            ..AppConfig::default()
        };
        let (system, user, has_org_context) =
            build_entity_dossier_prompt(&db, "Atlas", &unlocked, &cfg, "claude_code").unwrap();
        assert!(!has_org_context, "no org membership ⇒ has_org_context must be false");
        assert!(!user.contains("[org ·") && !system.contains("[org ·"));
    }

    /// Neither a local entity NOR any org context ⇒ the pre-org `InvalidArg` error semantics are
    /// preserved exactly (genuinely unknown entity).
    #[test]
    fn unknown_entity_with_no_org_context_still_errors() {
        let db = tmp_db();
        let unlocked = empty_unlocked();
        let cfg = AppConfig::default();
        let err = build_entity_dossier_prompt(&db, "Nonexistent Thing", &unlocked, &cfg, "claude_code")
            .unwrap_err();
        assert!(matches!(err, AppError::InvalidArg(_)));
    }
}

/// Generate a Weekly Vault Digest synthesizing meetings from the last `days` days; writes it
/// into the vault's Digests/ folder and returns the markdown + path.
#[tauri::command]
pub async fn generate_digest(
    state: State<'_, AppState>,
    days: i64,
) -> Result<DigestResult, AppError> {
    let days = days.clamp(1, 90);
    let config = {
        state
            .config
            .lock()
            .map_err(|_| AppError::Config("config mutex poisoned".into()))?
            .clone()
    };
    let cutoff = (chrono::Utc::now() - chrono::Duration::days(days)).to_rfc3339();
    // Budget on the NOTES-role provider's RESOLVED connection — the corpus egresses to it
    // (identical to `provider_id` while role keys are absent).
    let notes_conn =
        crate::summarize::roles::provider_target(crate::summarize::roles::Role::Notes, &config)
            .connection;
    let budget = if notes_conn == "ollama" {
        4_000
    } else {
        80_000
    };
    // Finding 2 + BLK-2b: build the cloud corpus from VISIBLE meetings + VISIBLE notes only, so a
    // sealed-and-not-unlocked meeting's TITLE (the `### [[title]]` header) AND markdown never leave
    // the device. `list_meetings_visible` + `get_note_if_visible` push the session unlock set
    // through the same predicate as MCP — correctness no longer depends on at-rest blanking.
    let unlocked = unlocked_snapshot(state.inner())?;
    let mut corpus = String::new();
    let mut count = 0usize;
    for m in state.db.list_meetings_visible(300, &unlocked)? {
        if m.started_at.as_str() < cutoff.as_str() {
            continue;
        }
        if corpus.len() >= budget {
            break;
        }
        let Some(note) = state.db.get_note_if_visible(&m.id, &unlocked)? else {
            continue;
        };
        let title = m.title.clone().unwrap_or_else(|| "(untitled)".to_string());
        let date = m
            .started_at
            .split(['T', ' '])
            .next()
            .unwrap_or("")
            .to_string();
        let header = format!("\n\n### [[{title}]] · {date}\n");
        let remaining = budget.saturating_sub(corpus.len() + header.len());
        if remaining < 200 {
            break;
        }
        corpus.push_str(&header);
        corpus.push_str(&note.markdown.chars().take(remaining).collect::<String>());
        count += 1;
    }
    if count == 0 {
        return Err(AppError::InvalidArg(format!(
            "no summarized meetings in the last {days} days"
        )));
    }
    let range_label = format!("the last {days} days");
    let provider = crate::summarize::provider_for(crate::summarize::roles::Role::Notes, &config, &state.heavy_inference)?;
    let (system, user) =
        crate::summarize::digest::build_digest_prompt(&corpus, &range_label, &config.note_language);
    let markdown = provider.complete(&system, &user).await?;

    let exported_path = match config.vault_path.as_deref().filter(|p| !p.is_empty()) {
        Some(vault) => {
            let now = chrono::Utc::now().to_rfc3339();
            crate::export::write_note(
                std::path::Path::new(vault),
                Some("Digests"),
                "Weekly Digest",
                &now,
                &markdown,
            )
            .ok()
            .map(|p| p.to_string_lossy().to_string())
        }
        None => None,
    };
    Ok(DigestResult {
        markdown,
        exported_path,
    })
}

// ── Brain v2 L5 — scheduled briefs (schedule CRUD + propose-accept runs) ─────────────────────────

/// All brief schedules (config rows — labels, timing, hints; no meeting content).
#[tauri::command]
pub fn list_brief_schedules(
    state: State<'_, AppState>,
) -> Result<Vec<crate::storage::models::BriefSchedule>, AppError> {
    state.db.list_brief_schedules()
}

/// Validate a brief schedule's user-editable fields (shared by create + update).
fn validate_brief_schedule(s: &crate::storage::models::BriefSchedule) -> Result<(), AppError> {
    if s.label.trim().is_empty() {
        return Err(AppError::InvalidArg("brief label is empty".into()));
    }
    if let Some(d) = s.day_of_week {
        if !(0..=6).contains(&d) {
            return Err(AppError::InvalidArg(
                "day_of_week must be 0 (Monday) … 6 (Sunday)".into(),
            ));
        }
    }
    if !(0..=23).contains(&s.hour_local) {
        return Err(AppError::InvalidArg("hour must be 0…23".into()));
    }
    if !(0..=59).contains(&s.minute_local) {
        return Err(AppError::InvalidArg("minute must be 0…59".into()));
    }
    if !(1..=90).contains(&s.scope_days) {
        return Err(AppError::InvalidArg("scope_days must be 1…90".into()));
    }
    Ok(())
}

/// Create one brief schedule. `day_of_week`: 0 = Monday … 6 = Sunday, `None` = daily. The runner
/// (`crate::brief_runner`) fires it at most once per local day; the first fire is the first 60s
/// tick at/after `hour:minute` local.
#[tauri::command]
pub fn create_brief_schedule(
    state: State<'_, AppState>,
    label: String,
    day_of_week: Option<i64>,
    hour_local: i64,
    minute_local: i64,
    scope_days: Option<i64>,
    prompt_hint: Option<String>,
) -> Result<crate::storage::models::BriefSchedule, AppError> {
    let schedule = crate::storage::models::BriefSchedule {
        id: uuid::Uuid::new_v4().simple().to_string(),
        label: label.trim().to_string(),
        day_of_week,
        hour_local,
        minute_local,
        scope_days: scope_days.unwrap_or(7),
        prompt_hint: prompt_hint.map(|h| h.trim().to_string()).filter(|h| !h.is_empty()),
        enabled: true,
        last_run_at: None,
        created_at: chrono::Utc::now().to_rfc3339(),
    };
    validate_brief_schedule(&schedule)?;
    state.db.insert_brief_schedule(&schedule)?;
    Ok(schedule)
}

/// Update one brief schedule's editable fields (label / timing / window / hint / enabled).
#[tauri::command]
pub fn update_brief_schedule(
    state: State<'_, AppState>,
    schedule: crate::storage::models::BriefSchedule,
) -> Result<(), AppError> {
    validate_brief_schedule(&schedule)?;
    state.db.update_brief_schedule(&schedule)
}

/// Delete one brief schedule AND its staged runs.
#[tauri::command]
pub fn delete_brief_schedule(
    state: State<'_, AppState>,
    schedule_id: String,
) -> Result<(), AppError> {
    state.db.delete_brief_schedule(&schedule_id)
}

/// The PENDING (proposed, not yet accepted/dismissed) brief runs — the FE's proposal cards.
/// `note_md` was synthesized by the runner from VISIBLE-ONLY content (empty unlock set — the
/// consolidation-job discipline), so it cannot contain sealed content AT synthesis time; and a
/// meeting sealed AFTER the proposal purges its pending runs inside the seal tx
/// (`Db::purge_pending_brief_runs_tx` — the lock-security LEAK fix, 2026-07-10), so a row this
/// returns never paraphrases a currently-sealed meeting. That pair is what makes this read safe
/// without a per-meeting gate (documented posture, see `crate::brief_runner` + `migrate_briefs`).
#[tauri::command]
pub fn list_brief_runs(
    state: State<'_, AppState>,
) -> Result<Vec<crate::storage::models::BriefRun>, AppError> {
    state.db.list_pending_brief_runs()
}

/// ACCEPT a proposed brief: export its markdown to `<vault>/Briefs/` (atomic write) and CONSUME
/// the staged `note_md` (the vault `.md` becomes the only copy). Returns the exported path.
#[tauri::command]
pub fn accept_brief(state: State<'_, AppState>, run_id: String) -> Result<String, AppError> {
    let run = state
        .db
        .get_brief_run(&run_id)?
        .ok_or_else(|| AppError::InvalidArg(format!("no brief run {run_id}")))?;
    if run.status != "pending" {
        return Err(AppError::InvalidArg("this brief was already handled".into()));
    }
    if run.note_md.trim().is_empty() {
        return Err(AppError::InvalidArg("this brief has no content".into()));
    }
    let vault = vault_path(state.inner())
        .ok_or_else(|| AppError::InvalidArg("set an Obsidian vault first (Settings)".into()))?;
    let label = state
        .db
        .list_brief_schedules()?
        .into_iter()
        .find(|s| s.id == run.schedule_id)
        .map(|s| s.label)
        .unwrap_or_else(|| "Brief".to_string());
    let path = crate::export::write_note(
        std::path::Path::new(&vault),
        Some("Briefs"),
        &label,
        &run.proposed_at,
        &run.note_md,
    )?;
    state
        .db
        .accept_brief_run(&run_id, &chrono::Utc::now().to_rfc3339())?;
    Ok(path.to_string_lossy().to_string())
}

/// DISMISS a proposed brief: the staged row (markdown included) is deleted outright.
#[tauri::command]
pub fn dismiss_brief(state: State<'_, AppState>, run_id: String) -> Result<(), AppError> {
    state.db.delete_brief_run(&run_id)
}

// ── Brain v2 L5 — MCP server config (list/add/remove + per-server consent + test) ───────────────

/// All configured MCP servers (connection config only).
#[tauri::command]
pub fn list_mcp_servers(
    state: State<'_, AppState>,
) -> Result<Vec<crate::storage::models::McpServer>, AppError> {
    state.db.list_mcp_servers()
}

/// Add one MCP server. `transport` is `"http"` (a JSON-RPC endpoint URL) or `"stdio"` (a LOCAL
/// PROCESS — `endpoint` must be an ABSOLUTE path).
///
/// ⚠️ stdio WARNING (surface this in the FE add-server flow): a stdio MCP server is ARBITRARY
/// CODE EXECUTION — Murmur launches that binary with your user's permissions every time the brain
/// queries it. Only add binaries you trust and control; the absolute-path requirement prevents
/// $PATH hijacking but does NOT make an untrusted binary safe. The server stays fail-closed
/// (absent from the brain's tools) until `consent_to_mcp_server` is granted.
#[tauri::command]
pub fn add_mcp_server(
    state: State<'_, AppState>,
    label: String,
    transport: String,
    endpoint: String,
    args: Option<Vec<String>>,
) -> Result<crate::storage::models::McpServer, AppError> {
    let label = label.trim().to_string();
    if label.is_empty() {
        return Err(AppError::InvalidArg("server label is empty".into()));
    }
    let endpoint = endpoint.trim().to_string();
    match transport.as_str() {
        "http" => {
            if !(endpoint.starts_with("http://") || endpoint.starts_with("https://")) {
                return Err(AppError::InvalidArg(
                    "an http MCP server needs an http(s):// endpoint URL".into(),
                ));
            }
        }
        "stdio" => {
            // ABSOLUTE-PATH-ONLY (defense-in-depth against $PATH hijacking; re-checked at spawn).
            if !std::path::Path::new(&endpoint).is_absolute() {
                return Err(AppError::InvalidArg(
                    "a stdio MCP server command must be an ABSOLUTE path".into(),
                ));
            }
        }
        _ => {
            return Err(AppError::InvalidArg(
                "transport must be \"http\" or \"stdio\"".into(),
            ))
        }
    }
    let server = crate::storage::models::McpServer {
        // Hyphen-free id so it embeds cleanly in the `mcp_<id>_query` tool name.
        id: uuid::Uuid::new_v4().simple().to_string(),
        label,
        transport,
        endpoint,
        args: args.unwrap_or_default(),
        enabled: true,
        consented: false, // fail-closed until the dedicated consent command flips it.
        created_at: chrono::Utc::now().to_rfc3339(),
    };
    state.db.insert_mcp_server(&server)?;
    Ok(server)
}

/// Remove one MCP server (its tool disappears from the brain on the next spec build).
#[tauri::command]
pub fn remove_mcp_server(state: State<'_, AppState>, server_id: String) -> Result<(), AppError> {
    state.db.delete_mcp_server(&server_id)
}

/// Grant the ONE-TIME per-server egress consent for an MCP server. Mirrors
/// `consent_to_web_search`: the dedicated command is the ONLY writer that can flip consent ON.
#[tauri::command]
pub fn consent_to_mcp_server(
    state: State<'_, AppState>,
    server_id: String,
) -> Result<(), AppError> {
    if state.db.get_mcp_server(&server_id)?.is_none() {
        return Err(AppError::InvalidArg(format!("no MCP server {server_id}")));
    }
    state.db.set_mcp_server_consented(&server_id, true)
}

/// Revoke an MCP server's egress consent — it drops out of the connector registry and the brain's
/// tool list on the next build (fail-closed).
#[tauri::command]
pub fn revoke_mcp_consent(
    state: State<'_, AppState>,
    server_id: String,
) -> Result<(), AppError> {
    state.db.set_mcp_server_consented(&server_id, false)
}

/// TEST a configured MCP server: JSON-RPC `initialize` + `tools/list`, returning the discovered
/// tool COUNT (never the tool metadata — server-supplied descriptions are untrusted input and stay
/// out of the FE/prompts). CONSENT-GATED like every other egress to the server: an unconsented or
/// disabled server refuses BEFORE any connection — for a stdio server the test LAUNCHES the
/// configured binary, so consent must come first.
#[tauri::command]
pub async fn test_mcp_server(
    state: State<'_, AppState>,
    server_id: String,
) -> Result<usize, AppError> {
    let server = state
        .db
        .get_mcp_server(&server_id)?
        .ok_or_else(|| AppError::InvalidArg(format!("no MCP server {server_id}")))?;
    if !server.enabled || !server.consented {
        return Err(AppError::Unavailable(
            "this MCP server needs your one-time consent first".into(),
        ));
    }
    let client = crate::connectors::mcp_client::McpClient::for_server(&server)
        .ok_or_else(|| AppError::InvalidArg("invalid MCP server configuration".into()))?;
    // Content-free egress ledger row for the ATTEMPT, recorded BEFORE the handshake like every
    // connector egress — a failing test connection is still attempted egress (for a stdio server
    // the probe launches the configured binary), and the privacy receipt must show it
    // (lock-security WEAKNESS fix, 2026-07-10). No query text exists here; the row carries only
    // the per-server attribution (see `mcp_probe_entry`).
    crate::summarize::egress_log::active_sink()
        .record(crate::summarize::egress_log::mcp_probe_entry(&server.id));
    client.initialize().await.map_err(AppError::from)?;
    let tools = client.list_tools().await.map_err(AppError::from)?;
    Ok(tools.len())
}

/// Topic Threads: cluster the per-meeting topic spans (from cached timelines) across the whole
/// library into cross-meeting threads. Deterministic, no LLM. Only meetings whose timeline has
/// been generated (viewed at least once) contribute.
#[tauri::command]
pub fn topic_threads(state: State<'_, AppState>) -> Result<Vec<TopicThread>, AppError> {
    // BLK-2b: cluster only VISIBLE meetings' timelines — a sealed-and-not-unlocked meeting's
    // timeline `data` is blanked at rest, but gate on visibility so threads never depend on that
    // blanking (and a sealed meeting's topics never surface cross-meeting).
    let unlocked = unlocked_snapshot(state.inner())?;
    let mut input = Vec::new();
    for m in state.db.list_meetings_visible(500, &unlocked)? {
        let Some(json) = state.db.get_timeline_data(&m.id)? else {
            continue;
        };
        let Ok(tl) = serde_json::from_str::<MeetingTimeline>(&json) else {
            continue;
        };
        if tl.topics.is_empty() {
            continue;
        }
        input.push(crate::summarize::threads::MeetingTopics {
            meeting_id: m.id,
            title: m.title.unwrap_or_else(|| "(untitled)".to_string()),
            started_at: m.started_at,
            topics: tl
                .topics
                .iter()
                .map(|t| (t.label.clone(), t.start_s, t.end_s))
                .collect(),
        });
    }
    Ok(crate::summarize::threads::build_threads(&input))
}

/// Export a meeting as an Obsidian Canvas (.canvas) — a spatial board of its topic spans.
/// Requires the timeline (open the meeting once). Returns the written path.
#[tauri::command]
pub fn export_canvas(state: State<'_, AppState>, meeting_id: String) -> Result<String, AppError> {
    // D4 READ-GATE: a sealed-and-not-unlocked meeting's timeline is blanked; refuse to build a
    // canvas from it. Fail closed.
    if !meeting_is_unlocked(state.inner(), &meeting_id)? {
        return Err(AppError::Locked(
            "this meeting's folder is locked — unlock it to export the canvas".into(),
        ));
    }
    let meeting = state
        .db
        .get_meeting(&meeting_id)?
        .ok_or_else(|| AppError::InvalidArg(format!("no meeting with id {meeting_id}")))?;
    let json = state.db.get_timeline_data(&meeting_id)?.ok_or_else(|| {
        AppError::InvalidArg("open the meeting once to generate its timeline first".into())
    })?;
    let mut tl: MeetingTimeline = serde_json::from_str(&json)
        .map_err(|e| AppError::InvalidArg(format!("bad timeline data: {e}")))?;
    // Same coverage-repair the Detail view applies (heal a legacy cache that ends short of the
    // recording) so the exported canvas spans the meeting instead of the provider's early cluster.
    let segments = state.db.get_segments(&meeting_id)?;
    crate::summarize::timeline::repair_coverage(&mut tl, &segments);
    let title = meeting.title.unwrap_or_else(|| "Meeting".to_string());
    let topics: Vec<(String, f64, f64)> = tl
        .topics
        .iter()
        .map(|t| (t.label.clone(), t.start_s, t.end_s))
        .collect();
    let canvas = crate::export::canvas::build_canvas(&title, &topics);
    let vault = {
        state
            .config
            .lock()
            .map_err(|_| AppError::Config("config mutex poisoned".into()))?
            .vault_path
            .clone()
    }
    .filter(|p| !p.is_empty())
    .ok_or_else(|| AppError::InvalidArg("set a vault folder in Settings first".into()))?;
    let vault_root = std::path::Path::new(&vault);
    // D5: the Canvas dir must resolve inside the vault root.
    let dir = assert_in_vault(vault_root, std::path::Path::new("Canvas"))?;
    std::fs::create_dir_all(&dir)
        .map_err(|e| AppError::Export(format!("create Canvas dir failed: {e}")))?;
    let fname: String = title
        .chars()
        .map(|c| match c {
            '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|' | '#' | '^' | '[' | ']' => ' ',
            c if c.is_control() => ' ',
            c => c,
        })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    let fname = if fname.is_empty() {
        "Meeting".to_string()
    } else {
        fname
    };
    // D5: re-assert the final file path stays inside the vault (fname is sanitized, but bind the
    // guarantee at the write site).
    let path = assert_in_vault(
        vault_root,
        &std::path::Path::new("Canvas").join(format!("{fname}.canvas")),
    )?;
    std::fs::write(&path, canvas)
        .map_err(|e| AppError::Export(format!("write canvas failed: {e}")))?;
    Ok(path.to_string_lossy().to_string())
}

/// Best-effort: the soonest macOS Calendar event in the next 60 minutes (title only). Returns
/// None if Calendar access is denied or there's nothing upcoming — never errors the UI.
#[tauri::command]
pub async fn next_calendar_event() -> Result<Option<CalendarEvent>, AppError> {
    let script = r#"set now to (current date)
set laterT to now + (60 * minutes)
set out to ""
try
  tell application "Calendar"
    repeat with c in calendars
      repeat with e in (every event of c whose start date is greater than or equal to now and start date is less than or equal to laterT)
        set out to out & (summary of e) & linefeed
      end repeat
    end repeat
  end tell
end try
return out"#;
    let res = tokio::task::spawn_blocking(move || {
        std::process::Command::new("osascript")
            .arg("-e")
            .arg(script)
            .output()
    })
    .await;
    let stdout = match res {
        Ok(Ok(o)) if o.status.success() => String::from_utf8_lossy(&o.stdout).into_owned(),
        _ => return Ok(None),
    };
    let title = stdout
        .lines()
        .map(str::trim)
        .find(|l| !l.is_empty())
        .map(str::to_string);
    Ok(title.map(|title| CalendarEvent { title, start: None }))
}

/// CALENDAR source (local, zero-OAuth, on-device): list the user's events in a window around now
/// via the bundled `meetnotes-calendar` EventKit sidecar — title, attendees, agenda. GRACEFUL on
/// every failure: sidecar missing / Calendar permission denied / timeout / malformed output →
/// an empty list, never an error, never a block. No network egress: reading the local calendar
/// stays on device.
#[tauri::command]
pub async fn list_calendar_events(app: AppHandle) -> Result<Vec<CalendarEventFull>, AppError> {
    // Default window: now-1h .. now+12h (60 back, 720 forward minutes).
    Ok(crate::calendar::fetch_events(&app, 60, 720).await)
}

/// Build a compact [`CalendarContext`] (title + attendees + agenda) for one event so the existing
/// pre-meeting brief / note pre-analysis can consume it (the brain already takes context). Looks
/// the event up by id in the same window the sidecar surfaces. Returns `None` if the event isn't
/// found (expired from the window, or Calendar access denied) — never an error.
///
/// IMPORTANT: the returned text is on-device context. If it is later fed to a CLOUD provider it
/// MUST ride the existing `make_provider` redaction firewall + consent (the same path the
/// transcript takes) — this command opens NO new egress path.
#[tauri::command]
pub async fn calendar_context_for(
    app: AppHandle,
    event_id: String,
) -> Result<Option<CalendarContext>, AppError> {
    if event_id.trim().is_empty() {
        return Err(AppError::InvalidArg("event_id is empty".into()));
    }
    let events = crate::calendar::fetch_events(&app, 60, 720).await;
    Ok(events
        .iter()
        .find(|e| e.id == event_id)
        .map(CalendarContext::from_event))
}

/// Read current config (settings table), without secrets.
#[tauri::command]
pub fn get_config(state: State<'_, AppState>) -> Result<AppConfigDto, AppError> {
    let config = state
        .config
        .lock()
        .map_err(|_| AppError::Config("config mutex poisoned".into()))?;
    Ok(config_to_dto(&config))
}

/// Build the ready-to-paste Claude Code MCP config block for the localhost MCP server, WITH the
/// bearer token when `mcp_require_token` is on (the default). Fixes the handshake failure where
/// the copied snippet had no token so Claude Code got `-32001 unauthorized` on `initialize`.
///
/// Shape (pretty-printed, 2-space indent — `type: "http"` is required by Claude Code):
/// ```json
/// {
///   "mcpServers": {
///     "murmur": {
///       "type": "http",
///       "url": "http://127.0.0.1:8765",
///       "headers": { "Authorization": "Bearer <token>" }
///     }
///   }
/// }
/// ```
/// When `mcp_require_token` is OFF the server serves unauthenticated, so the `headers` block is
/// omitted entirely (no stale/placeholder Authorization header is ever emitted).
///
/// SECURITY: this surfaces the MCP bearer token to the LOCAL frontend for display in Settings so
/// the user can paste it into their own Claude Code config. It is NOT network egress — the token
/// never leaves the machine except by the user's manual copy. When the token flag is off no token
/// is read at all. Lock-security review requested.
#[tauri::command]
pub fn get_mcp_config(state: State<'_, AppState>) -> Result<String, AppError> {
    get_mcp_config_inner(state.inner())
}

/// Headless core of [`get_mcp_config`] — testable without a Tauri `State`.
pub(crate) fn get_mcp_config_inner(state: &AppState) -> Result<String, AppError> {
    // Read the flag the same way lib.rs does: fail CLOSED (require the token) on a poisoned lock,
    // so a broken config never emits an unauthenticated config for a server that DOES enforce.
    let require_token = state
        .config
        .lock()
        .map(|c| c.mcp_require_token)
        .unwrap_or(true);

    let url = format!("http://127.0.0.1:{}", crate::mcp::MCP_PORT);
    let mut server = serde_json::json!({
        "type": "http",
        "url": url,
    });
    if require_token {
        // Only read/mint the token when the server actually enforces it. On a keychain failure this
        // returns AppError (the FE shows an error) — never a config with an empty/placeholder token.
        let token = crate::secrets::get_or_create_mcp_token()?;
        server["headers"] = serde_json::json!({
            "Authorization": format!("Bearer {token}"),
        });
    }
    let config = serde_json::json!({
        "mcpServers": { "murmur": server },
    });
    serde_json::to_string_pretty(&config)
        .map_err(|e| AppError::Other(anyhow::anyhow!("serialize MCP config: {e}")))
}

/// Persist config to settings table + refresh in-memory cache. Does NOT touch Keychain.
#[tauri::command]
pub fn save_config(
    app: AppHandle,
    state: State<'_, AppState>,
    config: AppConfigDto,
) -> Result<(), AppError> {
    save_config_inner(state.inner(), config)?;
    // Enforce the cap immediately when a save leaves auto-prune ON with a cap set (e.g. the
    // user just lowered the limit). Best-effort; the config lock is already released. Runs
    // BEFORE `restart_voice_listener` (which consumes `app`) so `app.emit` stays valid.
    let (limit_gb, auto) = match state.config.lock() {
        Ok(c) => (c.audio_storage_limit_gb, c.audio_auto_prune),
        Err(_) => (None, false),
    };
    if let Ok(dir) = crate::pipeline::audio_dir() {
        // Hold the seal lifecycle guard across the prune (config lock already released above, so
        // the lock order is lifecycle ⊃ db, never config held while holding lifecycle) so the
        // prune can never interleave with a folder seal.
        let _lifecycle = lifecycle_guard(state.inner());
        if let Ok(s) = crate::storage::usage::maybe_prune(&state.db, &dir, limit_gb, auto, None) {
            if s.freed_bytes > 0 {
                let _ = app.emit(
                    crate::events::EVENT_STORAGE_PRUNED,
                    crate::events::StoragePrunedPayload {
                        freed_bytes: s.freed_bytes,
                        pruned_count: s.pruned_count,
                    },
                );
            }
        }
    }
    // Reconcile the voice-trigger listener with the new config (AppHandle-dependent; runs after
    // the config lock is released by `save_config_inner`).
    restart_voice_listener(app);
    Ok(())
}

/// Headless core of [`save_config`]: validate, merge, persist, and refresh the in-memory cache.
/// No `AppHandle`/event emission here, so it is unit-testable without Tauri.
pub(crate) fn save_config_inner(state: &AppState, config: AppConfigDto) -> Result<(), AppError> {
    // Validate the gateway URL eagerly, before persisting, so a malformed or credential-bearing
    // URL (`https://key:@host/v1`) is never stored in the plaintext settings row and never
    // round-trips to the FE. An empty URL is allowed (no gateway configured).
    if !config.gateway_base_url.trim().is_empty() {
        crate::summarize::gateway::validate_gateway_url(&config.gateway_base_url)?;
    }
    // M3-CLIENT: validate the sharing-server URL at the same seam (reject embedded creds / http on a
    // non-loopback host) so a bad value is refused BEFORE it is persisted. Empty is allowed (unset).
    if !config.share_base_url.trim().is_empty() {
        crate::summarize::gateway::validate_gateway_url(&config.share_base_url)?;
    }

    // Merge against the CURRENT config under the config lock so the security-sensitive flags that
    // save_config must NOT be able to flip from the DTO (BLK-4: cloud_egress_consented) are read
    // from the live value, not the incoming payload. Holding the guard across the merge+save+swap
    // makes it atomic w.r.t. a concurrent `consent_to_cloud_egress`.
    let mut cache = state
        .config
        .lock()
        .map_err(|_| AppError::Config("config mutex poisoned".into()))?;
    let new_config = dto_to_config(config, &cache);
    new_config.save(&state.db)?;
    *cache = new_config;
    Ok(())
}

/// E10 — grant the one-time cloud-egress consent. This is the ONLY supported way to flip
/// `cloud_egress_consented` true: it persists the flag AND updates the in-memory config cache, so
/// the next `make_provider(claude_code|anthropic)` is allowed to build. Idempotent.
///
/// The FE calls this from its first-cloud-send confirmation dialog. Until the user confirms, every
/// cloud summarize/chat returns `AppError::Unavailable("cloud egress not consented …")`, which the
/// FE detects and surfaces as the consent prompt.
#[tauri::command]
pub fn consent_to_cloud_egress(state: State<'_, AppState>) -> Result<(), AppError> {
    let mut cache = state
        .config
        .lock()
        .map_err(|_| AppError::Config("config mutex poisoned".into()))?;
    cache.grant_cloud_egress_consent(&state.db)?;
    Ok(())
}

/// E10 — REVOKE the cloud-egress consent (the AI-settings privacy strip). Mirror of
/// [`consent_to_cloud_egress`] and the ONLY supported way to flip `cloud_egress_consented` false:
/// it persists the flag AND updates the in-memory config cache, so the NEXT
/// `make_provider(claude_code|anthropic|gateway)` / cloud-reasoner call is refused fail-closed
/// (`AppError::Unavailable`) — the gate re-reads the live config per call, no restart needed.
/// Idempotent; a settings save can still neither grant nor revoke (the DTO stays preserve-only).
#[tauri::command]
pub fn revoke_cloud_egress(state: State<'_, AppState>) -> Result<(), AppError> {
    let mut cache = state
        .config
        .lock()
        .map_err(|_| AppError::Config("config mutex poisoned".into()))?;
    cache.revoke_cloud_egress(&state.db)?;
    Ok(())
}

/// brain2 connectors — grant the one-time WEB SEARCH egress consent. The web connector reaches an
/// EXTERNAL service (a NEW EGRESS CLASS): the redacted query leaves the device. This is the ONLY
/// supported way to flip `web_search_consented` true; it persists the flag AND updates the in-memory
/// config cache, so the next `ConnectorRegistry::build` exposes the web tool (provided web search is
/// also enabled and a key is stored). Idempotent. Until granted, the web connector is absent from the
/// brain's tool registry and the redacted query never leaves the device.
#[tauri::command]
pub fn consent_to_web_search(state: State<'_, AppState>) -> Result<(), AppError> {
    let mut cache = state
        .config
        .lock()
        .map_err(|_| AppError::Config("config mutex poisoned".into()))?;
    cache.grant_web_search_consent(&state.db)?;
    Ok(())
}

/// One-time Jira egress consent — the ONLY way `jira_consented` flips true. Persists the flag AND
/// updates the in-memory config cache, so the next `ConnectorRegistry::build` exposes the jira tool
/// (provided Jira is also enabled + configured + a token is stored). Idempotent.
#[tauri::command]
pub fn consent_to_jira(state: State<'_, AppState>) -> Result<(), AppError> {
    let mut cache = state
        .config
        .lock()
        .map_err(|_| AppError::Config("config mutex poisoned".into()))?;
    cache.grant_jira_consent(&state.db)?;
    Ok(())
}

/// Store/replace the BYO Jira API token in the Keychain (account "jira_api_token"). An empty input
/// clears it. NEVER logged, NEVER returned to the FE — only `has_*` reports presence.
#[tauri::command]
pub fn set_jira_token(key: String) -> Result<(), AppError> {
    if key.trim().is_empty() {
        return secrets::delete_secret(crate::connectors::jira::JIRA_TOKEN_ACCOUNT);
    }
    secrets::set_secret(crate::connectors::jira::JIRA_TOKEN_ACCOUNT, key.trim())
}

/// Whether a Jira token is currently stored (UI shows "set"/"not set"; never the value).
#[tauri::command]
pub fn has_jira_token() -> Result<bool, AppError> {
    Ok(
        secrets::get_secret(crate::connectors::jira::JIRA_TOKEN_ACCOUNT)?
            .filter(|k| !k.trim().is_empty())
            .is_some(),
    )
}

/// One-time Slack egress consent — the ONLY way `slack_consented` flips true. Persists the flag AND
/// updates the in-memory config cache, so the next `ConnectorRegistry::build` exposes the slack tool
/// (provided Slack is also enabled + a token is stored). Idempotent.
#[tauri::command]
pub fn consent_to_slack(state: State<'_, AppState>) -> Result<(), AppError> {
    let mut cache = state
        .config
        .lock()
        .map_err(|_| AppError::Config("config mutex poisoned".into()))?;
    cache.grant_slack_consent(&state.db)?;
    Ok(())
}

/// Store/replace the BYO Slack user token in the Keychain (account "slack_user_token"). An empty
/// input clears it. NEVER logged, NEVER returned to the FE — only `has_*` reports presence.
#[tauri::command]
pub fn set_slack_token(key: String) -> Result<(), AppError> {
    if key.trim().is_empty() {
        return secrets::delete_secret(crate::connectors::slack::SLACK_TOKEN_ACCOUNT);
    }
    secrets::set_secret(crate::connectors::slack::SLACK_TOKEN_ACCOUNT, key.trim())
}

/// Whether a Slack token is currently stored (UI shows "set"/"not set"; never the value).
#[tauri::command]
pub fn has_slack_token() -> Result<bool, AppError> {
    Ok(
        secrets::get_secret(crate::connectors::slack::SLACK_TOKEN_ACCOUNT)?
            .filter(|k| !k.trim().is_empty())
            .is_some(),
    )
}

